import type { Post } from './posts';

// Original Turkish editorial guides. HTML is static and never accepts user input.
type Chapter = [heading: string, prose: string];
function article(slug: string, title: string, engineering: boolean, excerpt: string, chapters: Chapter[], references: number[], related = 'cidr-alt-ag-hesaplama'): Post {
  return { slug, date: '2026-10-11', category: engineering ? 'Network Engineering' : 'IP Adresleri ve Ağ Temelleri', title: {tr: title}, excerpt: {tr: excerpt}, body: {tr: `<p>${excerpt}</p>${chapters.map(([heading, prose]) => `<h2>${heading}</h2><p>${prose}</p>`).join('')}<h2>Kaynaklar ve devam okuması</h2><p>Teknik dayanaklar: ${references.map(n => `<a href="https://www.rfc-editor.org/rfc/rfc${n}.html">RFC ${n}</a>`).join(', ')}. Kaynak kontrolü: 11 Ekim 2026. Senaryolar açıklama amaçlıdır; gerçek ortam ölçümü veya ürün performans iddiası değildir.</p><p>İlgili rehber: <a href="/tr/blog/${related}">konuyu tamamlayan uygulama adımları</a>.</p>`} };
}

export const infinityFoundations: Post[] = [
article('noktadan-noktaya-31-adres-plani', 'İki yönlendirici arasında /31 adresleme ne zaman doğrudur?', false,
'Bir transit bağlantı için dört IPv4 adresi ayırmak her zaman gerekli değildir. /31 kullanımını ağ türü, cihaz desteği ve işletim araçlarıyla birlikte değerlendirin.', [
['İki uç ile kullanıcı ağı aynı değildir', 'RFC 3021, noktadan noktaya IPv4 bağlantısında iki adresin de uç adresi olarak kullanılabilmesini tanımlar. Bu istisnayı bir ofis VLAN’ına taşımayın: çok sayıda istemcinin bulunduğu yayın ağı farklı bir tasarım problemidir. Önce bağlantının gerçekten iki yönlendirici arasında olduğunu, cihazların ilgili arayüzde bu öneki desteklediğini ve kurum standardınızın buna izin verdiğini belirleyin. Adres kazanımı kadar izleme ve envanter uyumluluğu da kararın parçasıdır.'],
['Örnek adres çiftini hesaplamak', 'Laboratuvarda 10.20.0.0/31 bloğunu ele alın. Uçlar .0 ve .1 adreslerini kullanır; sonraki çift 10.20.0.2/31 olur. Hesap tablosunda “ağ adresi kullanılamaz” şeklinde yazılmış genel bir formül .0 adresini yanlış işaretleyebilir. Envanter doğrulamanızı bağlantı türüne göre düzenleyin. Aynı tablodaki .2 adresini ilk bağlantının üçüncü üyesi sanmak, kablolama doğru olsa bile komşuluğu bozacaktır.'],
['Geçişi nasıl sınarsınız?', 'Önce ayrı bir test bağlantısı oluşturun. Karşılıklı erişimi, yönlendirme komşuluğunu, yönetim adresine ulaşmayı ve izleme sisteminin iki ucu ayrı kaydetmesini kontrol edin. Bir test başarısı diğerlerinin yerine geçmez: ping çalışan bağlantıda yönlendirme kimlik doğrulaması hâlâ yanlış olabilir. Üretimde değişiklik yapılacaksa iki ucun ayarlarını, bağımsız yönetim erişimini ve eski /30 planını geri dönüş kaydına ekleyin.'],
['Kabul ölçütünü belirlemek', 'Başarıyı yalnızca iki adres tasarrufu diye raporlamayın. Her uç doğru arayüze bağlı olmalı, komşuluk yeniden kurulmalı ve bağlantı kesilip geldiğinde aynı davranış tekrarlanmalıdır. İzleme aracı .0 adresini atlıyorsa aracın sürümünü veya hedef tanımını düzeltmeden yaygınlaştırmayın. Desteklenmeyen eski cihazlarda /30 kullanımı makul bir uyumluluk kararıdır. Plan, ağı işleten ekibin hata yapmadan okuyabildiği kadar değerlidir.']
], [3021, 1812]),
article('tekil-rota-32-ve-loopback', '/32 rota ile loopback adresi arasındaki ilişkiyi kurmak', false,
'Tek adresi temsil eden /32 öneki, fiziksel bağlantıdan bağımsız yönetim ve belirli hedefe özel yönlendirme için kullanılır. Adresin tanımı ile erişim yolunu ayrı düşünün.', [
['Adres bir yolu garanti etmez', 'Bir yönlendiricide 10.255.0.7/32 tanımlamak o adrese bütün ağdan ulaşılacağı anlamına gelmez. Diğer cihazların bu hedefe giden bir rotası ve geri dönüş yolu bulunmalıdır. Loopback arayüzü, kabloya bağlı arayüzden farklı bir işletim ömrü sunabilir; ancak cihazın kendisi veya onu taşıyan yollar erişilemez olduğunda hizmet de erişilemez olur. “Loopback her zaman çalışır” cümlesi bu yüzden yanıltıcıdır.'],
['İki bağlantılı yönlendirici örneği', 'A yönlendiricisinin B ve C üzerinden iki yolu olduğunu düşünün. Yönetim sistemi A’nın fiziksel B bağlantısındaki adresine bağımlıysa o bağlantı kaybında oturum bozulabilir. Yönetim için A’nın loopback adresini kullanmak adresi sabit tutar; iki yolun da bu adresi taşıması ayrıca yapılandırılır. İzleme ekibi arayüz durumu ile yönetim adresinin erişimini ayrı testlerle takip etmelidir.'],
['Kayıt ve doğrulama', 'Envantere adres, cihaz, amaç, yönlendirme alanı ve ilan politikasını yazın. /32 kaydını yerel bir kullanıcı alt ağı gibi yorumlayıp yanına ağ geçidi hesabı eklemeyin. Hedefe farklı noktalardan erişim deneyin ve yanıtın kaynak adresini kaydedin. Yönetim ACL’si loopback hedefini kabul ederken yanıtın dönüş yolu başka güvenlik bölgesinden geçebilir; başarılı yönlendirme güvenlik politikasını kendiliğinden oluşturmaz.'],
['Yanlış genellemeyi önlemek', 'Bir /32 rota statik, dinamik veya yerel olabilir. Dolayısıyla tabloda /32 görmek adresin kesinlikle loopback olduğunu kanıtlamaz. Belirli bir sunucu için VPN üzerinden tanımlanmış host route da aynı uzunluğu taşır. Değişiklik öncesi rotanın kaynağını ve sonraki atlamasını kontrol etmek, doğru hedefi yanlış bağlantıya yönlendirme riskini azaltır.']
], [4632, 1812]),
article('ipv6-metin-normalizasyonu', 'IPv6 adreslerini metin olarak karşılaştırmak neden hatalıdır?', false,
'Aynı IPv6 adresi farklı yazılışlarla görünebilir. Envanter, arama ve tekrar kayıt denetiminde önce adresi çözümleyip sonra standart biçimde gösterin.', [
['Görüntü ile değer farklıdır', '2001:0db8:0000:0000:0000:0000:0000:0001 ile 2001:db8::1 aynı sayısal adresi ifade eder. Büyük harfler, baştaki sıfırlar ve sıfır gruplarının kısaltılması metni değiştirir. RFC 5952 tutarlı gösterim için kurallar sunar. Veritabanında yalnızca ham dizgeyi benzersiz anahtar yapmak aynı cihaz için iki kayıt oluşturabilir; bu sorun ağda iki ayrı adres olduğu anlamına gelmez.'],
['İçe aktarma senaryosu', 'Bir CSV dosyasında uzun gösterim, tarama çıktısında kısa gösterim bulunduğunu düşünün. Önce güvenilir bir IP ayrıştırıcısıyla her girdinin geçerliliğini doğrulayın. Başarılı girdileri sayısal veya sabit uzunluklu ikili karşılığa dönüştürün; kullanıcıya standart metni gösterin. Hatalı girdileri sessizce düzeltmek yerine satır numarasıyla ayırın. Özellikle iki kez kullanılan çift iki nokta gibi biçimleri tahmin ederek kabul etmeyin.'],
['Adresin bağlamını saklamak', 'Aynı link-local adres farklı arayüzlerde bulunabilir. Bu nedenle standartlaştırılmış adres her koşulda küresel bir cihaz kimliği değildir. Kayıtta ağ kapsamını veya arayüzü ayrıca saklayın. URL içindeki IPv6 adreslerinin köşeli parantezle kullanılması da adres değerinden ayrı bir sunum kuralıdır. Kullanıcıdan gelen URL’yi doğrudan IP sütununa yazmak, port bilgisini yanlışlıkla adresin parçası yapabilir.'],
['Test kümesini hazırlamak', 'Karşılaştırma testine uzun ve kısa eşdeğerleri, farklı son haneyi, geçersiz kısaltmayı ve link-local kapsamını ekleyin. Eşdeğerler tek kayıt olurken farklı adresler birleşmemelidir. Ham değeri denetim amacıyla saklamak yararlıdır; ancak arama ve tekilleştirme için çözümlenmiş alanı kullanın. Sonuçların neden birleştirildiğini gösteren kayıt, operatörün otomatik işlemi denetlemesini kolaylaştırır.']
], [5952, 4007], 'ipv6-adres-turleri'),
article('localhost-dinleme-adresi', '127.0.0.1, 0.0.0.0 ve ağ adresinde dinleme nasıl ayrılır?', false,
'Bir hizmetin hangi adreste dinlediği, hangi istemcilerin ona ulaşabileceğini belirler. Yerelde çalışan uygulamanın diğer bilgisayarda açılmamasını üç ayrı katmanda inceleyin.', [
['Dinleme adresini okuyun', 'Loopback adresi aynı makine içindeki iletişim içindir. Uygulamanın 127.0.0.1 üzerinde dinlemesi başka bilgisayarların bu adrese erişmesini sağlamaz; onların 127.0.0.1 adresi kendilerini gösterir. Birçok soket API’sinde 0.0.0.0 tüm yerel IPv4 arayüzleri üzerinde dinleme seçeneğidir. Bu değeri tarayıcıya yazılacak uzak sunucu adresi olarak paylaşmak doğru değildir. IPv6 davranışı işletim sistemi ve soket seçenekleriyle ayrıca değerlendirilir.'],
['Yerel geliştirme örneği', 'Dizüstü bilgisayarda 8080 portunda çalışan paneli aynı Wi-Fi içindeki telefonda açmak istiyorsunuz. Önce panelin dinleme adresini kontrol edin; ardından dizüstünün gerçek LAN adresini belirleyin. Uygulama yalnızca loopback üzerinde ise telefon erişimi beklemeyin. Dinleme kapsamını genişletmek geliştirme panelini ağdaki diğer kullanıcılara da açabileceğinden kimlik doğrulama ve güvenlik duvarı kapsamını birlikte planlayın.'],
['Katmanları sırayla sınamak', 'Önce sunucuda yerel HTTP isteğini, sonra aynı sunucuda LAN adresine isteği, ardından izin verilen başka cihazdan bağlantıyı deneyin. İlk adım başarısızsa ağ cihazlarını araştırmak erken olur. İlk iki adım başarılı, üçüncü başarısızsa güvenlik duvarı, istemci izolasyonu veya yol politikasını inceleyin. Her denemede kullanılan adres ve portu kaydedin; farklı portları karşılaştırmak teşhisi yanıltır.'],
['Açık portu hizmetle karıştırmayın', 'TCP bağlantısının kurulması doğru web uygulamasına erişildiğini tek başına kanıtlamaz. Ters proxy, Host başlığı veya TLS adı farklı sonucu doğurabilir. Dinleme kapsamını düzelttikten sonra gerçek kullanıcı isteğini doğrulayın. Gereksiz yere bütün arayüzleri açmak yerine gereken ağ arayüzünü veya güvenlik duvarındaki kaynak kapsamını seçmek daha denetlenebilir bir sonuç verir.']
], [1122, 4291], 'tcp-udp-port-farki'),
article('broadcast-hedefinin-siniri', 'Yayın adresini bilmek neden bütün cihazları bulmaya yetmez?', false,
'Broadcast, bir bağlantıdaki alıcılara yönelik iletim biçimidir. Yayın hedefine gönderilen tek istekten eksiksiz cihaz envanteri çıkarmak mümkün değildir.', [
['Adres hesabı ile yanıt politikası', 'IPv4 alt ağının yayın adresi önek uzunluğuna bağlıdır. 192.168.40.0/26 için son adres .63 olur; .255 farklı bir kapsamı temsil eder. Doğru yayın adresini hesaplamak yalnızca hedefi belirler. Cihazın ilgili uygulamayı çalıştırması, isteği kabul etmesi ve yanıtın geri ulaşması ayrıca gerekir. Broadcast isteğine yanıt vermeyen cihaz, normal tekil bağlantılara cevap verebilir.'],
['İki VLAN örneği', 'Bilgisayar VLAN 10, yazıcı VLAN 20 içinde olsun. Bir keşif uygulamasının yerel yayın göndermesi yazıcıya otomatik ulaşmaz. Yönlendirilmiş erişim bulunması, bütün yerel keşif protokollerinin VLAN sınırını geçtiği anlamına gelmez. Çözümü ağ maskesini büyütmekte aramayın. Ürünün desteklediği hedefli keşfi veya onaylanmış hizmet aktarma mekanizmasını değerlendirin; her protokol için aynı röle çalışmaz.'],
['Eksik sonucu doğru raporlamak', 'Keşif çıktısına yöntem, kaynak arayüz, saat ve hedef kapsamını ekleyin. “Ağda 8 cihaz var” yerine “Bu yöntemle 8 yanıt alındı” ifadesi daha doğrudur. Sonucu DHCP kayıtları ve switch bilgisiyle birleştirirken kayıt yaşlarını dikkate alın. Kira kaydı mevcut olup yayın yanıtı olmayan cihaz kapanmış da olabilir, yayını filtreliyor da olabilir.'],
['Trafik yükünü sınırlamak', 'Tekrarlanan yayınlar aynı bağlantıdaki çok sayıda alıcıyı meşgul edebilir. Önce küçük bir zaman penceresinde kontrollü deneme yapın, otomatik tekrarları sınırlandırın ve bilinen cihazla doğrulayın. Yayın tabanlı keşfi internet üzerinden çalışacak genel bir yöntem gibi tasarlamayın. Protokolün kapsamını korumak hem daha öngörülebilir sonuç hem de daha sakin bir ağ sağlar.']
], [919, 1812], 'cidr-alt-ag-hesaplama'),
article('en-uzun-onek-eslesmesi', 'VPN açıkken trafik neden beklenmedik yoldan gider?', false,
'Rota seçimini yalnızca varsayılan ağ geçidine bakarak açıklayamazsınız. Hedefi kapsayan daha özel önek, başka bir bağlantının tercih edilmesine yol açabilir.', [
['Önce eşleşen önekleri bulun', '10.0.0.0/8 ve 10.24.0.0/16 rotaları aynı anda bulunuyorsa 10.24.5.8 hedefi daha uzun /16 önekiyle eşleşir. Aynı önek için birden çok adayın seçimi ise işletim sistemi veya yönlendirme protokolünün ek kurallarına bağlıdır. Bu iki aşamayı karıştırıp her sorunu metrik düşürerek çözmeye çalışmak, ilgisiz hedeflerin yolunu da değiştirebilir.'],
['Ev ağı ve şirket ağı örneği', 'Ev ağı 192.168.1.0/24, VPN’deki şirket ağı da aynı aralığı kullanıyor olsun. Uzak dosya sunucusunu hedeflediğinizde sistem yerel bağlantıda komşu arayabilir. VPN bağlı simgesi yalnızca tünelin kurulduğunu gösterir; çakışan adres planını ortadan kaldırmaz. Önce hedef IP’yi ve seçilen arayüzü doğrulayın. Kalıcı çözüm çoğunlukla adres planı veya kontrollü VPN rotası düzenlemesidir.'],
['Salt okunur inceleme', 'Windows’ta route print çıktısını VPN kapalı ve açık durumlarda karşılaştırın. Varsayılan rota, hedefe özel rota ve arayüz numarasını not edin. Hassas kurum adreslerini paylaşmadan önce çıktıyı uygun şekilde maskeleyin. Uzaktan çalışırken rotayı silmek yönetim oturumunu koparabileceğinden ilk incelemeyi değişiklik yapmadan tamamlayın. Aynı hedefe DNS adından ve IP’den erişim farkı varsa isim çözümünü ayrı ele alın.'],
['Dönüş yolunu unutmayın', 'İstemcinin doğru tünele göndermesi, sunucunun yanıtı aynı erişilebilir yoldan döndüreceğini garanti etmez. Sunucu tarafındaki rota ve güvenlik politikası da gereklidir. Sonucu yalnızca tek yönde paket gördüğünüz için tamamlanmış saymayın. Gerçek uygulama oturumu, doğru kaynak adresi ve dönüş trafiği birlikte doğrulandığında sorun açıklanabilir hâle gelir.']
], [4632, 3704], 'varsayilan-ag-gecidi'),
article('ipv6-kaynak-adresi-secimi', 'Bir cihazın birden fazla IPv6 adresi varsa hangisi kullanılır?', false,
'IPv6 envanterindeki bütün adresler her bağlantıda aynı rolü üstlenmez. Kaynak adresi seçimi, uygulama davranışı ve adres ömrü birlikte değerlendirilmelidir.', [
['Adres listesi bağlantı listesi değildir', 'İstemci aynı arayüzde link-local, kalıcı ve geçici adresler taşıyabilir. RFC 6724 varsayılan kaynak ve hedef seçimine ilişkin bir çerçeve tanımlar; uygulama veya yönetici politikası seçim üzerinde etkili olabilir. Bu nedenle ekranda ilk görülen adresin her isteğin kaynağı olduğunu varsaymayın. Özellikle yalnızca belirli kaynak öneklerini kabul eden güvenlik kuralları bu varsayımla yanlış tasarlanabilir.'],
['İki adresli istemci senaryosu', 'Bir dizüstünün envanterinde kalıcı A adresi ve geçici B adresi bulunduğunu düşünün. Sunucu günlüğünde B görülürken envanterde A üzerinden arama yapmak cihazın kaybolduğu izlenimini yaratabilir. Olay kaydına saat, kaynak port ve ağ kapsamını ekleyin. Tek başına bir IP eşleşmesi kullanıcı kimliğini kesin olarak belirlemez; cihaz yönetimi ve oturum kayıtlarıyla desteklenmelidir.'],
['Seçimi gözlemleyin', 'İzinli bir test sunucusuna bağlantı kurun ve sunucunun gördüğü kaynak adresi istemcideki adres listesiyle karşılaştırın. Testi farklı hedef kapsamları için yineleyin; sonuçları ölçüm saatiyle saklayın. Uygulama belirli adrese bağlanabiliyorsa bu seçeneği yalnızca kontrollü deneyde kullanın. Sistem genelindeki öncelik tablosunu değiştirmek başka uygulamaların bağlantı davranışını da etkileyebilir.'],
['Operasyonel karar', 'Güvenlik tasarımını tek bir geçici istemci adresine kalıcı izin vermek üzerine kurmayın. Gereken durumlarda kimlik tabanlı erişim veya yönetilen ağ kapsamları daha sürdürülebilir olur. Sorunu gidermek için IPv6’yı kapatmadan önce yanlış seçimin mi, eksik yönlendirmenin mi, yoksa hatalı ACL’nin mi söz konusu olduğunu ayırın. Adres çokluğu, tek başına arıza belirtisi değildir.']
], [6724, 8981], 'ipv6-adres-turleri'),
article('gecici-ipv6-envanter-kaydi', 'Geçici IPv6 adresleri cihaz envanterini nasıl etkiler?', false,
'Bir cihazın yeni IPv6 adresiyle görünmesi yeni donanım bağlandığını kanıtlamaz. Geçici adresleri zaman ve cihaz bağlamıyla ilişkilendiren bir envanter modeli kurun.', [
['Değişimin nedenini ayırın', 'Geçici IPv6 adresleri adres üzerinden uzun süreli ilişkilendirmeyi azaltmayı amaçlayan mekanizmalardır. Bunlar anonimlik garantisi vermez; uygulama hesabı ve başka tanımlayıcılar ilişki kurabilir. Envanter açısından önemli sonuç, tek cihaz ile tek IP arasındaki bire bir ilişkinin geçersiz olmasıdır. Sürekli yeni cihaz alarmı üreten sistem önce adres ömrünü ve toplama yöntemini incelemelidir.'],
['Kayıt modelini düzenlemek', 'Cihaz tablosu ile adres gözlemleri tablosunu ayırın. Adres kaydına ilk görülme, son görülme, kaynak yöntem ve ağ kapsamı ekleyin. Aynı fiziksel cihazın iki adresini birleştirmek için yalnızca benzer metne güvenmeyin; yönetilen cihaz kimliği veya doğrulanmış arayüz ilişkisi gerekir. Gözlem yokluğunu silinme olarak değil, belirli bir zamanda görülmeme olarak kaydetmek daha dürüsttür.'],
['Örnek alarm incelemesi', 'Pazartesi 30, salı 48 IPv6 adresi gözlenmesi 18 yeni bilgisayar anlamına gelmeyebilir. Önce aktif yönetilen cihaz sayısını, adres geçerlilik durumlarını ve tarama kapsamını karşılaştırın. Adreslerin bir kısmı eski oturumlar için korunuyor olabilir. Bu örnek bir ölçüm sonucu değil, sayım mantığını sınayan senaryodur; raporda hangi varlığın sayıldığı açıkça belirtilmelidir.'],
['Gizlilik ile işletimi dengelemek', 'Sorunu çözmek adına bütün istemcilerin geçici adreslerini kapatmak geniş bir ürün ve gizlilik kararıdır. Önce envanterin ilişkilendirme yöntemini düzeltin, kayıt saklama süresini tanımlayın ve yalnızca gerekli alanları toplayın. Yönetim erişimi için kararlı adlar veya yönetilen uç nokta sistemleri kullanmak, kullanıcı trafiğinin her adresini kalıcı kimliğe dönüştürmekten farklı bir ihtiyaçtır.']
], [8981, 4862], 'ipv6-adres-turleri'),
article('ula-ipv6-birlesme-plani', 'ULA adresleri iki şirket ağını birleştirirken nasıl planlanır?', false,
'IPv6 ULA planı, kurum içindeki adresleri sistemli yönetmeye yardımcı olur. Yerel kullanım ile internet erişimini ve kuruluş birleşmesinde çakışma riskini ayrı ele alın.', [
['Öneki rastgele seçmek ne demektir?', 'RFC 4193 yerel olarak atanmış ULA önekleri için sözde rastgele bir Global ID yaklaşımı tanımlar. Her kurumda aynı kolay hatırlanan öneki kullanmak bu tasarımın amacını zayıflatır. ULA, küresel internet üzerinde normal yönlendirme beklentisiyle kullanılmaz; güvenlik duvarının yerini de tutmaz. Yerel adres olmak, bütün kurum içi kullanıcıların o adrese erişmesine izin vermek anlamına gelmez.'],
['Birleşme öncesi envanter', 'İki şirketin VPN kuracağı bir senaryoda önce mevcut ULA bloklarını, VLAN dağılımını ve DNS bölgelerini çıkarın. Adreslerin yalnızca ilk birkaç hanesini karşılaştırmayın; önek uzunluğunu ve alt ağ kimliklerini kaydedin. Çakışma varsa tünel kurulduktan sonra rastgele rota eklemek yerine yeniden adresleme planını hazırlayın. Bağımlı uygulama izinleri ve sabit adres tanımları da envantere girmelidir.'],
['Pilot bölüm seçmek', 'Küçük bir test VLAN’ında yeni planı uygulayın. İstemci adres seçimini, yerel hizmet erişimini ve DNS yanıtını gözlemleyin. ULA ile global adres aynı anda varsa uygulamanın hangi hedefi seçtiğini doğrulayın. Yalnızca ping testi yapmak, işletmenin kullandığı uygulamanın doğru adres ailesine ve güvenlik bölgesine geçtiğini kanıtlamaz.'],
['Kalıcı kayıt oluşturmak', 'Önek üretimini, sorumlu ekibi, tahsis tarihini ve kullanılmayan blokları merkezi kayda ekleyin. Görsel açıdan hoş bir numaralandırma uğruna çakışma olasılığını artırmayın. Yeni şube için gereken alanı bugünkü cihaz sayısının yanında büyüme ve yönlendirme düzeniyle değerlendirin. Planın başarısı, sonraki ekibin hangi bloğun kime ait olduğunu tahmin etmeden bulabilmesidir.']
], [4193, 6724], 'ipv6-adres-turleri'),
article('dokuman-ip-adresleri', 'Teknik belgelerde neden gerçek IP yerine örnek adres kullanılır?', false,
'Eğitim metinlerinde rastgele seçilmiş genel adresler gerçek sistemlere ait olabilir. Dokümantasyon için ayrılmış adresleri kullanarak örneklerin sınırını açıkça gösterin.', [
['Doğru örnek blokları', 'IPv4 için 192.0.2.0/24, 198.51.100.0/24 ve 203.0.113.0/24 dokümantasyon bloklarıdır. IPv6’da 2001:db8::/32 bu amaçla ayrılmıştır. Bu adresler kullanıcıya internette çalışan bir test sunucusu olarak sunulmamalıdır. Bir komut örneğine eklediğiniz hedefin açıklama amaçlı olduğunu yazmak, okuyucunun sonuç alamadığında kendi ağını gereksiz yere değiştirmesini önler.'],
['Destek kaydını paylaşmak', 'Bir müşterinin yönlendirme çıktısını teknik makaleye dönüştürürken adresleri gelişigüzel silmek ilişkiyi bozabilir. Aynı orijinal öneki bütün örneklerde aynı dokümantasyon öneğine eşleyin. Önek uzunluklarını ve topolojik ilişkileri koruyun; müşteri adı, kullanıcı adı ve anahtar gibi diğer hassas alanları ayrıca temizleyin. IP maskelemesi tek başına kaydı anonim yapmaz. Paylaşım onayı, saklama kapsamı ve ekran görüntülerindeki diğer tanımlayıcılar yayın öncesinde ayrıca denetlenmelidir.'],
['Uygulama örneği', 'İki sağlayıcılı bir çizimde birinci sağlayıcıyı 192.0.2.0/30, ikinciyi 198.51.100.0/30 ile gösterin. Sunucu örneğini 203.0.113.10 olarak adlandırın. Bunların gerçek bağlantı kurulacak hedefler olmadığını şeklin yanında belirtin. Yerel laboratuvar kuracak okuyucu kendi yetkili adres planını kullanmalıdır; yazıdaki değerleri üretim yönlendiricisine olduğu gibi kopyalamamalıdır.'],
['Yayın öncesi kontrol', 'Metin, görsel, kod ve ekran görüntüsündeki adresleri birlikte tarayın. Aynı örnekte bir gerçek adresin kalması bağlamı açığa çıkarabilir. DNS adları ve URL’ler için de örnek amaçlı isimlendirme politikanızı uygulayın. Dış bağlantı verilen gerçek kaynaklar ise ayrı tutulmalıdır: okuyucunun teknik standarda ulaşmasını sağlayan kaynak URL’sini örnek diye geçersiz bir adrese çevirmeyin.']
], [5737, 3849], 'ip-adresi-nedir'),
article('ipv6-multicast-kapsami', 'IPv6 multicast kapsamı paketlerin nereye gideceğini nasıl sınırlar?', false,
'Bir multicast adresindeki kapsam bilgisi, grup üyeliği kadar önemlidir. Aynı grup fikrinin her yönlendirici üzerinden otomatik taşınacağını varsaymayın.', [
['Grup ile kapsamı ayırmak', 'IPv6 multicast adresleri grup tanımlamasının yanında kapsam alanı taşır. Link-local kapsam bir bağlantıyla sınırlıdır; daha geniş kapsam farklı işletim gereksinimleri doğurur. Adresi yalnızca “ff ile başlıyor” diye sınıflamak teşhis için yetersizdir. Uygulamanın beklediği kapsamı, gönderen arayüzü ve alıcının bulunduğu bağlantıyı birlikte okuyun. IPv6’da IPv4 tarzı broadcast bulunmaması, her multicast grubunun herkese teslim edileceği anlamına gelmez.'],
['İki arayüzlü bilgisayar', 'Ethernet ve Wi-Fi aynı anda açık bir bilgisayarda uygulama yanlış arayüz üzerinden grup trafiği gönderebilir. Alıcı doğru ağa bağlı olsa bile sonuç görünmez. Sorunu multicast adresini değiştirerek çözmeye çalışmadan önce soketin seçtiği arayüzü ve yerel grup üyeliklerini inceleyin. Arayüz kapsamının uygulama tarafından açıkça belirtilmesi gereken durumlar vardır.'],
['Kontrollü gözlem', 'Aynı bağlantıda bilinen bir alıcıyla başlayın. Gönderilen paket, alıcının grup üyeliği ve güvenlik duvarı kararı birbirinden ayrı kanıtlardır. Daha sonra ikinci bağlantıya geçip yönlendirme tasarımının bu akışı destekleyip desteklemediğini kontrol edin. Yerelde çalışan deneyi kurum çapında çalışacak uygulama olarak sunmayın; kapsam değiştiğinde güvenlik ve trafik dağıtım gereksinimleri de değişir.'],
['Kayıt biçimi', 'Destek kaydına tam grup adresi, kapsam, arayüz adı, kaynak adres ve uygulama portunu ekleyin. Sadece “multicast çalışmıyor” ifadesi hangi katmanda hata olduğunu göstermez. Farklı kapsamların karışmasını önleyen kayıtlar, yazılım ekibiyle ağ ekibinin aynı deneyi yeniden üretmesini sağlar. Yetki verilmeyen ağlara yayılmayı önlemek, doğru tasarımın doğal bir parçasıdır.']
], [4291, 4007], 'ipv6-komsu-kesfi'),
article('nat-hairpin-yerel-erisim', 'Genel adresten çalışan hizmet neden içeriden açılmaz?', false,
'Aynı genel adrese dışarıdan ve içeriden erişmek NAT cihazında farklı yollar oluşturabilir. Hairpin davranışını DNS, port yönlendirme ve hizmet doğrulamasından ayırın.', [
['İçeriden dış adrese dönmek', 'İstemci ve sunucu aynı özel ağdayken istemcinin sunucunun genel eşlemesine gitmesi, NAT üzerinden içeri dönen bir akış gerektirebilir. UDP için NAT davranış gereksinimleri RFC 4787’de ele alınır; belirli cihazın bütün protokollerdeki desteğini bundan varsayamazsınız. Üretici sürümü, eşleme ve güvenlik kuralları uygulamadaki sonucu etkiler. Dışarıdan erişimin çalışması içeri dönüş yolunun da çalıştığını kanıtlamaz.'],
['Üç ayrı test', 'Önce sunucuya yerel adresinden izin verilen portla erişin. Ardından gerçekten dış bir bağlantıdan genel adrese erişin. Son olarak içeriden aynı genel adresi deneyin. Bu üç deneyin yalnızca sonuncusu başarısızsa hairpin veya içeride farklı DNS yanıtı olasılığı anlamlıdır. Telefonun Wi-Fi yerine hücresel bağlantıda olduğundan emin olmadan “dış test” yaptığınızı varsaymayın.'],
['İç DNS alternatifi', 'Bazı tasarımlarda aynı hizmet adı içeride özel, dışarıda genel adres döndürür. Bu yaklaşım DNS yönetimi, sertifika adı ve istemci önbelleği açısından birlikte planlanmalıdır. Kullanıcılara farklı IP ezberletmek yerine hizmet adının tutarlı kalması yararlı olabilir. Ancak kayıt değişikliği çalışan dış erişimi bozmamalı; özel adresin dış DNS’e sızmadığı ayrıca doğrulanmalıdır.'],
['Güvenli sonuç değerlendirmesi', 'Sorunu gidermek için yönetim panelini bütün internete açmayın veya güvenlik duvarını bütünüyle kapatmayın. Gereken akışın kaynak, hedef ve port kapsamını belirleyin. Paket kaydında NAT öncesi ve sonrası adreslerin farklı olabileceğini dikkate alın. Çözümden sonra hem iç hem dış erişimi, yetkisiz kaynakların reddedilmesini ve doğru uygulama yanıtını kontrol edin.']
], [4787, 6056], 'cgnat-nasil-anlasilir'),
article('gecici-portlar-oturum-kimligi', 'İstemcinin geçici portu bir bağlantıyı nasıl ayırt eder?', false,
'Sunucu portu hizmeti tanımlar; istemcinin kaynak portu ise aynı hizmete açılan eşzamanlı akışları ayırmaya yardımcı olur. Günlük incelemesinde iki tarafı birlikte kaydedin.', [
['Port tek başına kimlik değildir', 'Bir TCP akışı genellikle kaynak ve hedef IP ile kaynak ve hedef portun birleşimi üzerinden ayırt edilir. İstemci kaynak portlarının seçimi işletim sistemi ve yapılandırmaya bağlıdır. Kaynak portunun 443 olması akışın mutlaka HTTPS sunucusu tarafından başlatıldığı anlamına gelmez. Protokol, yön ve bağlam okunmadan yalnızca bir sayıdan hizmet veya kullanıcı çıkarımı yapılmamalıdır.'],
['İki sekmeli tarayıcı örneği', 'Aynı bilgisayarın aynı sunucuya farklı kaynak portlarından bağlantılar açabildiğini düşünün. NAT bu portları dış tarafta yeniden eşleyebilir. Sunucu günlüğündeki adres ve port ile istemci tarafındaki kaydın bire bir görünmemesi bu yüzden mümkündür. Eşleştirme için aynı zaman aralığındaki NAT kaydı gerekir; yalnızca genel IP birçok kullanıcı tarafından paylaşılabilir.'],
['Teşhis için gerekli alanlar', 'Kayda protokol, iki IP, iki port, başlangıç zamanı ve gözlem noktasını ekleyin. NAT öncesi kayıt ile NAT sonrası kaydı ayrı etiketleyin. Zamanı saniyeye yuvarlamak yoğun sistemlerde birden fazla olayı aynı ana sıkıştırabilir; eldeki hassasiyeti açıkça belirtin. Gizlilik politikasına uygun olmayan gereksiz oturum kayıtlarını sırf ileride lazım olur diye süresiz saklamayın.'],
['Tükenmeyi yorumlamak', 'Çok sayıda kısa bağlantı veya sınırlı NAT kapasitesi yeni oturum kurulmasını etkileyebilir. Her bağlantı hatasını port tükenmesi diye adlandırmayın; hata kodu, eşzamanlı oturum sayısı ve cihaz kapasitesi gerekir. Sürekli zaman aşımı görüldüğünde DNS, sunucu limitleri ve yol kaybını da ayırın. Kaynak portu gözlemi güçlü bir ipucudur, tek başına tam açıklama değildir.']
], [6056, 4787], 'tcp-udp-port-farki'),
article('ip-parcalama-uygulama-boyutu', 'IP parçalanması neden büyük uygulama mesajlarında sorun çıkarır?', false,
'Küçük isteklerin çalışıp büyük mesajların kaybolması, yol MTU’su ve parçalanma davranışıyla ilişkili olabilir. Mesaj boyutunu paket boyutuyla karıştırmadan inceleyin.', [
['Parça kaybının etkisi', 'IP parçalanması büyük bir IP datagramını daha küçük parçalara ayırabilir; parçaların yeniden birleştirilmesi için gerekli parçaların ulaşması gerekir. Ara cihazlar veya güvenlik kuralları parçalara farklı davranabilir. RFC 8900 parçalanmanın kırılganlığını açıklar. Bu, her büyük uygulama mesajının tek büyük IP datagramı olarak gönderildiği anlamına gelmez; taşıma protokolü ve uygulama davranışı önemlidir.'],
['Kontrollü boyut deneyi', 'Aynı sunucuya küçük ve daha büyük istekleri aynı yoldan gönderin. Her boyutta birden fazla deneme yapın ve kaybın belirli eşikte mi yoksa düzensiz mi oluştuğunu kaydedin. Laboratuvar dışındaki yükü artırmayın. Paket yakalaması yapılabiliyorsa izinli ortamda IP boyutunu ve parça bilgisini inceleyin; uygulama arayüzündeki dosya boyutu bunun yerine geçmez.'],
['Tünel farkını karşılaştırmak', 'VPN kapalıyken çalışan, açıkken bozulan büyük aktarım ek kapsülleme nedeniyle daha küçük kullanılabilir MTU’ya işaret edebilir. Ancak VPN güvenlik politikası veya sunucu erişim farkı da aynı belirtiyi üretebilir. İki durumda hedefin, protokolün ve uygulama sürümünün aynı kaldığını doğrulayın. Rastgele MTU azaltmak yerine ölçüm ve cihaz belgeleriyle değişikliği gerekçelendirin.'],
['Kalıcı düzeltme', 'Uygun yol MTU keşfi, doğru tünel MTU’su ve uygulama mesaj tasarımı birlikte değerlendirilir. Güvenlik duvarında gerekli kontrol mesajlarını körlemesine engellemek teşhisi zorlaştırabilir. Düzeltmeden sonra yalnızca ping değil, başlangıçta bozulan gerçek aktarım sınanmalıdır. Sonuca kullanılan paket boyutunu ve yol koşullarını eklemek sonraki değişikliklerde karşılaştırılabilir bir kayıt sağlar.']
], [8900, 8200], 'ping-yaniti-yok'),
article('ip-adresi-sayisal-siralama', 'IP adresleri neden metin sırasıyla yanlış sıralanır?', false,
'192.168.1.100 adresinin 192.168.1.20’den önce görünmesi ağ hatası değildir. Listeleme ve aralık hesabında metin karşılaştırması yerine adres değerini kullanın.', [
['Dizge sırası farklı bir işlemdir', 'Metin sıralaması karakterleri karşılaştırır; adres sıralaması ise sayısal alanları dikkate almalıdır. IPv4 dört sekiz bitlik parçadan oluşur. “100” ile “20” dizgelerinin alfabetik karşılaştırılması, 100 ile 20 sayılarının karşılaştırılmasıyla aynı sonucu vermez. Kullanıcıların yanlış aralık seçmesini önlemek için tablo sıralamasını görünür metinden bağımsız bir adres anahtarına bağlayın.'],
['Envanter uygulaması örneği', 'Bir listede .2, .20 ve .100 cihazları olsun. Dört parçayı doğrulayıp her birini 0–255 aralığında sayıya dönüştürmek doğru sıralamayı sağlar. Eksik parça, işaretli sayı veya boş alan geldiğinde girdiyi reddedin; tahmin ederek tamamlamayın. Kullanılan dilde bit işlemlerinin işaretli tamsayı üretip üretmediğini kontrol edin. Büyük IPv4 değerlerinin negatif sıralanması farklı bir uygulama hatasıdır.'],
['IPv6 için ayrı yaklaşım', 'IPv6 adreslerini sırf iki noktalardan bölerek aynı yöntemle işlemeyin; kısaltılmış grupların açılması gerekir. Güvenilir ayrıştırıcıdan sabit uzunluklu değer alın. Karışık IPv4 ve IPv6 listelerinde aile sırasını ürün kararı olarak açıkça belirleyin. Adresle birlikte port veya önek uzunluğu gösteriliyorsa bunları bağımsız alanlarda tutmak hem aramayı hem doğrulamayı kolaylaştırır.'],
['Doğrulama kümesi', 'Sınır değerleri, eşdeğer IPv6 gösterimleri, geçersiz girdiler ve aynı adresin farklı kapsamlarını test edin. Sıralamanın ekranda düzelmesi veri modelindeki tekrarları kendiliğinden kaldırmaz; tekilleştirme de çözümlenmiş değere dayanmalıdır. Dışa aktarılan CSV’nin daha sonra başka bir programda metin olarak sıralanabileceğini açıklayın. Kullanıcıya görünür düzen ile dosyadaki ham veri aynı sorumluluk değildir.']
], [791, 5952], 'ip-adresi-nedir'),
article('ipv6-zone-id-arayuz', 'fe80:: adresinin sonundaki yüzde işareti neyi belirtir?', false,
'Link-local IPv6 adresi tek başına hangi fiziksel bağlantının kullanılacağını her zaman söylemez. Kapsam kimliği, özellikle çok arayüzlü cihazlarda hedefi belirsizlikten çıkarır.', [
['Aynı adres, farklı bağlantı', 'Bir bilgisayarda iki farklı bağlantıda fe80::1 bulunabilir. Kapsam veya zone tanımı hangi bağlantının kastedildiğini belirtir. Bazı komutlarda yüzde işaretinden sonra arayüz adı ya da sayısı kullanılır. Bu gösterim, IPv6 adresinin 128 bitlik değerine yeni bitler eklemez. İşletim sistemleri arayüz kimliğini farklı biçimde gösterebildiği için bir makinedeki sayıyı başka makineye aynen taşımayın.'],
['İki adaptörlü örnek', 'Ethernet ve sanal makine adaptöründe aynı link-local hedef görüldüğünü düşünün. Yanlış arayüz kimliğiyle yapılan deneme tamamen farklı bağlantıya gider. Önce sistemin arayüz listesinden hedef ağla eşleşen adaptörü bulun. Ardından kullandığınız komutun kapsam sözdizimini kendi işletim sistemi belgesinden doğrulayın. Sonuca hem adresi hem arayüz adını yazın; yalnızca adres destek ekibine yeterli bağlam sağlamaz.'],
['Veri modelindeki etkisi', 'Envanterde link-local adresleri global adreslerle aynı tekillik kuralına sokmayın. Adres ve ağ kapsamı birlikte değerlendirilmelidir. CSV dışa aktarmada kapsam bilgisini ayrı sütunda tutmak daha taşınabilirdir. Kullanıcı yeniden içe aktardığında eski arayüz numarası başka bir adaptöre ait olabilir; otomatik eşleşmeyi doğrulamadan bağlantı başlatmayın.'],
['Sınırı doğru anlatmak', 'Link-local hedefe erişim başarılıysa yalnızca ilgili bağlantı içindeki erişim kanıtlanır. Bu başarı internet rotasının, DNS’in veya uzak site bağlantısının sağlıklı olduğunu göstermez. Aynı şekilde başarısız deneme yanlış kapsamdan kaynaklanabilir ve cihazın kapalı olduğunu kanıtlamaz. Kapsamı açık kayıtlar tutmak, bu iki yanlış sonuca karşı en basit korumadır.']
], [4007, 4291], 'ipv6-komsu-kesfi'),
article('dhcp-secenekleri-adres-disinda', 'DHCP adres verdiği hâlde internet neden çalışmayabilir?', false,
'Başarılı DHCP alışverişi yalnızca bir adres görünmesiyle değerlendirilmemelidir. Maske, yönlendirici ve DNS gibi seçenekleri aynı yapılandırmanın parçaları olarak kontrol edin.', [
['Kira ile kullanılabilir yapılandırma', 'DHCP seçenekleri istemciye adresin yanında farklı ağ parametreleri iletebilir. Yanlış DNS sunucusu verilen istemci IP hedeflerine erişirken isimle bağlantıda sorun yaşayabilir. Hatalı maske yerel kabul edilen hedefleri değiştirebilir. Bu yüzden “adres alıyor” bulgusu, “ağ doğru yapılandırılmış” sonucuna eşit değildir. İstemcinin aldığı değerleri onaylanmış kapsam ayarlarıyla karşılaştırın.'],
['Yeni VLAN örneği', 'Yeni personel VLAN’ında istemciler beklenen 10.40.20.0/24 bloğundan adres alıyor, ancak uygulama adları çözülmüyor olsun. Önce DNS adreslerinin eski VLAN’dan kopyalanıp kopyalanmadığını inceleyin. DNS sunucusuna erişim izni de farklı olabilir. Tek bir bilgisayarda elle genel DNS tanımlayarak sorunu örtmek, iç şirket adlarının çözülmesini daha da bozabilir.'],
['Karşılaştırmalı inceleme', 'Çalışan ve çalışmayan istemcide IP, maske, ağ geçidi, DNS sırası ve DHCP sunucusunu kaydedin. İki cihaz farklı kapsamdan yapılandırma alıyorsa farkın tasarlanmış mı hatalı mı olduğunu belirleyin. Kira yenilemesi uzaktaki erişimi etkileyebileceğinden önce salt okunur çıktıları toplayın. Sunucu ayarı değişmiş olsa bile mevcut istemcinin eski değerleri koruyabildiğini hesaba katın.'],
['Düzeltmeyi yaygınlaştırmak', 'Önce küçük istemci grubunda doğru seçenekleri doğrulayın. Gerçek uygulamanın adla erişimi, yerel hizmetler ve internet erişimi ayrı ayrı sınanmalıdır. Kapsam değişikliğinin ne zaman istemcilere yansıyacağını ve geri dönüşte hangi değerlerin kullanılacağını kaydedin. Başarı raporunda yalnızca sunucu ekran görüntüsünü değil, istemcinin aldığı yapılandırmayı göstermek değişikliğin gerçekten ulaştığını kanıtlar.']
], [2132, 2131], 'dhcp-kira-suresi'),
article('slaac-adres-omru', 'IPv6 adresindeki preferred ve valid süreleri nasıl okunur?', false,
'Bir IPv6 adresinin yeni bağlantılar için tercih edilmemesi, o adresin hemen geçersiz olduğu anlamına gelmez. Adres ömrünü bağlantı sürekliliğiyle birlikte değerlendirin.', [
['İki farklı yaşam süresi', 'SLAAC adreslerinde preferred ve valid lifetime kavramları bulunur. Tercih edilen süre sona erdiğinde adres deprecated durumuna geçebilir; geçerlilik süresi başka bir sınırı ifade eder. Bu ayrım, yeniden adresleme sırasında yeni iletişimlerin yeni adrese yönelirken bazı mevcut iletişimlerin sürmesine yardımcı olur. Tam davranış uygulama, işletim sistemi ve ağ koşullarıyla ayrıca sınanmalıdır.'],
['Önek değişikliği senaryosu', 'Bir ofiste eski IPv6 öneğinden yenisine geçildiğini düşünün. İstemcide iki önekten adres görülmesi geçişin doğal bir parçası olabilir. Envanterin eski adresi anında silmesi, hâlen devam eden bağlantıları açıklamayı zorlaştırır. Eski ve yeni önek için gözlem zamanını, tercih durumunu ve ilan bilgilerini kaydedin. Adresin listede bulunması tek başına yeni bağlantılarda kullanılacağını göstermez.'],
['İnceleme adımları', 'İstemcide adres durumunu okuyun, yönlendirici ilanının planlanan sürelerle uyumunu kontrol edin ve yeni bağlantıda seçilen kaynak adresi gözlemleyin. Mevcut uzun oturumla yeni oturumu ayrı deneyler olarak ele alın. Tüm istemcilerin aynı anda yenileneceğini varsaymayın; uyuyan veya bağlantısı kesilmiş cihazlar farklı zamanda yeni yapılandırmayı öğrenebilir.'],
['Geçişi kapatma koşulu', 'Eski öneki yönlendirmeden kaldırmadan önce bağımlı hizmetleri, DNS kayıtlarını ve güvenlik izinlerini kontrol edin. Yalnızca çoğunluğun yeni adres aldığını görmek kalan kullanıcıların etkilenmeyeceğini kanıtlamaz. Planlı geçiş penceresi, gözlem süresi ve geri dönüş eşiği belirleyin. İki yaşam süresini açıkça belgelemek, adres değişikliğini rastgele bir kesinti olmaktan çıkarır.']
], [4862, 6724], 'ipv6-adres-turleri'),
article('dns-negatif-onbellek-yeni-kayit', 'Yeni DNS kaydı eklendiği hâlde neden bulunamayabilir?', false,
'Daha önce bulunamayan bir isim için olumsuz yanıt da önbelleğe alınabilir. Yeni kayıt yayımlandığında bütün çözümleyicilerin anında aynı yanıtı vermesini beklemeyin.', [
['Yokluk yanıtının ömrü', 'DNS negatif önbellekleme, başarısız isim veya veri aramalarının belirli kurallarla geçici saklanmasını sağlar. RFC 2308 bu davranışın temelini açıklar. Yeni bir kayıt eklemek önceki olumsuz cevabı bütün ara önbelleklerden anında silmez. Bu yüzden yeni kaydın TTL değerini düşürmek, daha önce oluşmuş her negatif yanıtı hemen geçersiz yapacak bir işlem değildir.'],
['Yayın sırası örneği', 'Ekip henüz oluşturulmamış portal adını test eder ve isim bulunamaz. Birkaç dakika sonra kayıt eklenir, ancak aynı istemci hâlâ hata alır. Önce yetkili DNS’in doğru cevabı verdiğini kontrol edin. Ardından kullanılan recursive çözümleyicinin yanıtını karşılaştırın. Yetkili sunucu da yanlışsa beklemek çözüm değildir; kayıt adı, bölge veya delegasyon hatası olabilir.'],
['Yerel temizliğin sınırı', 'İstemcinin DNS önbelleğini temizlemek yalnızca o katmanı etkiler. Kurumsal çözümleyici veya tarayıcının ayrı davranışı varsa sonuç değişmeyebilir. Denemede hangi sunucuya sorgu gönderildiğini kaydedin; farklı DNS sunucularından alınan sonuçları tek bir sistemin tutarsızlığı gibi sunmayın. NXDOMAIN ile SERVFAIL yanıtını ayırmak burada da önemlidir.'],
['Daha sakin yayın planı', 'Yeni hizmet adı önceden hazırlanıp doğrulanabilir; ardından uygulama erişimi açılır. Kayıt değişikliğini, sertifika hazırlığını ve hizmet başlangıcını aynı saniyeye sıkıştırmak teşhisi zorlaştırır. Yayın kontrol listesine yetkili yanıt, seçilen çözümleyici yanıtı ve gerçek HTTPS isteğini ekleyin. Başarılı DNS cevabı uygulamanın doğru hizmet verdiğinin son testi değildir.']
], [2308, 2132], 'nxdomain-servfail'),
article('anycast-adresi-konum', 'Aynı IP adresi neden farklı şehirlerdeki sunuculara ulaşabilir?', false,
'Anycast, aynı hizmet adresine giden trafiğin yönlendirme kararlarıyla farklı düğümlere ulaşmasına izin verir. Adresi fiziksel sunucu kimliği gibi kullanmayın.', [
['Yakınlık yalnızca kilometre değildir', 'Anycast işletiminde aynı adres farklı noktalardan duyurulabilir. Kullanıcının eriştiği düğüm ağın yönlendirme kararına bağlıdır; coğrafi olarak en yakın konum garanti edilmez. Bu nedenle tek bir IP’nin konum veritabanındaki şehir bilgisi hizmetin o anda hangi düğümden yanıt verdiğini kanıtlamaz. Ağ politikasının değişmesi aynı kullanıcıyı başka düğüme taşıyabilir.'],
['Destek incelemesi örneği', 'İstanbul’daki ve Ankara’daki iki ofis aynı DNS hizmet adresini kullanıyor fakat farklı gecikme görüyor olsun. Önce ölçüm zamanı, erişim sağlayıcısı ve hedef hizmeti kaydedin. Adres aynı diye yolun da aynı olduğunu varsaymayın. Hizmetin sunduğu düğüm kimliği veya tanılama bilgisi varsa kullanın; sadece traceroute adlarından kesin fiziksel konum çıkarmayın.'],
['Süreklilik tasarımı', 'Bir düğümün duyuruyu çekmesi trafiği başka yere taşıyabilir, ancak bütün uygulamalar oturum değişimine aynı şekilde dayanmaz. Uzun bağlantılar, yerel durum ve yeniden deneme davranışı hizmet tasarımında ele alınmalıdır. Anycast etiketini tek başına yüksek erişilebilirlik garantisi olarak sunmak doğru değildir. Yol ve düğüm değişimini kontrollü hata senaryosunda uygulama düzeyinde sınayın.'],
['Envantere yansıması', 'Hizmet adresini düğüm yönetim adresinden ayrı kaydedin. Operatörün aynı IP altında birden fazla dağıtım noktası olabildiğini görmesi gerekir. Alarmda hizmetin genel erişimini ve tek düğümün sağlık durumunu ayırın. Bir düğüm çalışırken kullanıcıların bir kısmının sorun yaşaması mümkündür; gözlem noktası çeşitliliği bu nedenle tek merkezli testten daha açıklayıcıdır.']
], [4786, 4271], 'ip-adresi-nedir'),
article('adres-plani-topoloji-hiyerarsisi', 'Şube adres planını topolojiye göre tasarlamak', true,
'Adres dağıtımı yalnızca boş bir blok bulmak değildir. Şube, işlev ve büyüme sınırlarını yönlendirme yapısıyla uyumlu tutmak günlük işletimi kolaylaştırır.', [
['İlk karar sayılar değildir', 'Planlamaya şube sayısını, güvenlik bölgelerini, bağlantı biçimini ve beklenen büyümeyi yazarak başlayın. Her şubeye aynı büyüklükte alan vermek okunabilir olabilir, fakat gerçek ihtiyaçtan çok büyük veya yetersiz bloklar yaratabilir. CIDR özetlemeye olanak tanır; iyi bir özet için blokların sayısal olarak bitişik olması kadar aynı yönlendirme sınırında bulunması da önemlidir.'],
['Küçük plan örneği', 'Üç şubeye 10.64.0.0/20, 10.64.16.0/20 ve 10.64.32.0/20 ayırdığınızı düşünün. Her şubenin içindeki kullanıcı, telefon ve yönetim ağları daha küçük bloklardan oluşturulabilir. Henüz kullanılmayan alanı rezerv olarak açıkça işaretleyin. Ancak şubeler farklı sağlayıcılardan çıkıyorsa merkezden tek özet duyurmanın arıza anındaki davranışını ayrıca değerlendirin. Güzel görünen tablo tek başına doğru trafik yolu üretmez.'],
['Envanter alanları', 'Her tahsise sahip ekip, kullanım amacı, VLAN, yönlendirme alanı ve durum ekleyin. “Boş” ile “gelecek proje için ayrılmış” aynı durum değildir. VPN ortaklarının ve bulut ağlarının mevcut bloklarını plan öncesinde kontrol edin. Aynı özel aralık iki bağımsız ağda geçerli olsa da bu ağlar birleştiğinde çakışma operasyonel maliyet yaratır.'],
['Planı sınamak', 'Bir şubenin bağlantısı koptuğunda özet rotanın trafiği yanlış yere çekip çekmediğini masa başı senaryosunda inceleyin. Yeni bir VLAN eklemek için önekleri değiştirmek gerekip gerekmediğine bakın. Bir sonraki ekibin tahsis yapacağı adımları yazın; yalnızca mimarın zihninde kalan kural sürdürülemez. Başarı ölçütü, yeni ağı mevcut kayıtlarla çakıştırmadan ve gereksiz yeniden numaralandırma yapmadan ekleyebilmektir.']
], [4632, 4193]),
article('rota-ozetleme-bosluklar', 'Özet rota içindeki kullanılmayan adresler nereye gider?', true,
'Birden çok rotayı tek önekte birleştirmek tabloyu sadeleştirir, fakat özetin kapsadığı boşluklar ayrıca düşünülmelidir. Hata senaryosunda döngü oluşturmayan bir tasarım kurun.', [
['Özet bir erişilebilirlik iddiasıdır', '10.80.0.0/16 duyurusu, yalnızca kullanılan birkaç /24’ü değil bütün bloğu kapsar. Daha özel rotalar mevcut hedefler için doğru yolu seçebilir; boş alan için cihazın başka bir yolu olabilir. Özeti duyuran yönlendiricinin üst tarafa varsayılan rota kullanması bazı tasarımlarda trafiği geri döndürebilir. Özetleme politikasını düşürme veya discard davranışıyla birlikte tasarlamak gerekir.'],
['İki yönlendiricili senaryo', 'Merkez şubeye 10.80.0.0/16 gönderiyor, şube merkeze varsayılan rota kullanıyor olsun. Şubede yalnızca 10.80.1.0/24 ve 10.80.2.0/24 varsa 10.80.90.5 hedefinin nasıl ele alınacağını açıkça belirleyin. Boş bloğa yönelik paket gerçek bir hizmete ulaşmayacaktır; ancak ağın gereksiz yere bu paketi dolaştırmaması beklenir. Bu senaryoyu canlı kullanıcı trafiği üretmeden laboratuvarda inceleyin.'],
['Arıza durumu da boşluk yaratır', 'Başlangıçta çalışan bir alt ağın rotası çekildiğinde özet hâlâ duyurulabilir. Kullanıcı, toplu rotayı gördüğü için alt ağın çalıştığını sanmamalıdır. İzleme sisteminde özetin varlığıyla alt hizmetin sağlığını ayrı takip edin. Özetin hangi koşulda ilan edildiğini ve bileşen rota kaybında davranışını cihaz belgelerinden doğrulayın; farklı platform varsayılanları aynı olmayabilir.'],
['Değişiklik kontrolü', 'Özet öncesi ve sonrası rota tablosunu karşılaştırın. Kullanılan her alt ağa, ayrılmış boş aralığa ve dış hedefe beklenen davranışı yazın. Yeni bir ağ eklendiğinde discard rota daha özel rotanın önüne geçmemelidir; önek uzunluğu ve politika birlikte kontrol edilir. Sadeleştirme, gözlemlenebilirliği kaybettirmediğinde işletim faydası sağlar.']
], [4632, 1812], 'varsayilan-ag-gecidi'),
article('ecmp-akis-dagilimi', 'ECMP varken tek dosya aktarımı neden iki hattı doldurmaz?', true,
'Eş maliyetli yolların bulunması, tek bağlantının toplam kapasiteyi kullanacağı anlamına gelmez. Trafik dağıtımının paket mi akış mı temelinde olduğunu öğrenin.', [
['Toplam kapasite ile tek akış', 'Birçok ECMP uygulaması akışın başlık alanlarından türetilen bir seçime göre yol belirler. Aynı akışın paketlerini aynı yolda tutmak sıralama sorunlarını azaltabilir. Bu nedenle iki eş hızlı hat üzerinden tek TCP aktarımının iki kat hız vermesini beklemek yanlış olabilir. Gerçek dağıtım alanları, karma algoritması ve donanım sınırları platforma bağlıdır; RFC 2992 bir algoritma incelemesidir, bütün ürünlerin garantisi değildir.'],
['Doğru test yükü', 'İki yolun her birinin varsayımsal olarak 1 Gbit/s olduğunu düşünün. Bir akış ve ardından birden çok bağımsız akışla ayrı deneyler yapın. Uç cihazların işlemci veya depolama sınırına takılmadığını kontrol edin. Çok akışlı sonuç daha yüksekse bu tek başına hatların eşit yüklendiğini göstermez; her çıkışın sayaçlarını aynı zaman aralığında okuyun.'],
['Dengesizliği açıklamak', 'Az sayıda büyük akış tesadüfen aynı yola düşebilir. Her bağlantıda tam yüzde elli paylaşım beklemek uygun kabul ölçütü değildir. Ayrıca tünel içindeki çok sayıda kullanıcı dış başlıklarda aynı akış gibi görünebilir. Donanımın iç başlıkları kullanıp kullanmadığını öğrenmeden karma ayarını değiştirmeyin; değişiklik mevcut akışların yolunu da etkileyebilir.'],
['Hata anını sınamak', 'Yollardan biri kaybolduğunda hangi akışların yeniden dağıtıldığını, uygulama kesintisini ve geri gelen yolun etkisini izleyin. Ortalama throughput yanında yeniden iletim ve oturum devamlılığına bakın. Sonuçları “iki hat var” diye özetlemek yerine testteki akış sayısı, protokol ve uç kapasitesiyle birlikte raporlayın. Kapasite planı ancak bu bağlamla tekrarlanabilir.']
], [2992, 6349], 'hiz-testi-dogru-olcum'),
article('asimetrik-rota-guvenlik-duvari', 'Asimetrik yönlendirme durum bilgili güvenlik duvarını nasıl etkiler?', true,
'İstek ile yanıtın farklı yollardan geçmesi bazı ağlarda normaldir. Ancak oturum durumunu izleyen cihazlar ve kaynak doğrulama kuralları bu tasarımla uyumlu olmalıdır.', [
['İki yönün kanıtını toplayın', 'A noktasında isteği görmek, yanıtın aynı noktaya döneceğini kanıtlamaz. İki çıkışlı ağlarda dönüş yolu başka cihazı kullanabilir. Durum bilgili güvenlik duvarı gerekli oturum bilgisini görmüyorsa akışı reddedebilir; kümelerde durum paylaşımı ve ürün davranışı ayrıca önemlidir. Asimetriyi otomatik olarak hata saymak yerine yolun mevcut güvenlik mimarisinde desteklenip desteklenmediğini belirleyin.'],
['İki sağlayıcı örneği', 'İstek birinci sağlayıcı ve F1 üzerinden çıkarken dönüş ikinci sağlayıcı ve F2’ye geliyor olsun. F2 günlüğündeki oturum bulunamadı benzeri olay, uygulamanın dinlemediğini göstermez. Aynı zaman aralığında iki cihazdaki kayıtları ve NAT eşlemelerini karşılaştırın. Gerçek günlük ile varsayımsal açıklamayı ayırın; yalnızca rota diyagramına bakarak belirli paketin hangi yoldan geçtiğine karar vermeyin.'],
['Kaynak doğrulama etkisi', 'Strict reverse path forwarding gibi mekanizmalar, dönüş rotasına göre gelen arayüzü değerlendirebilir. Çok bağlantılı tasarımda seçilen doğrulama yöntemi meşru asimetrik trafiği etkileyebilir. Çözüm bütün kaynak kontrolünü kaldırmak değildir; topolojiye uygun doğrulama, filtreleme ve yönlendirme birlikte planlanır. Geniş bir güvenlik istisnası oluşturmak yerine hangi öneklerin hangi yollardan gelebileceğini yazın.'],
['Düzeltmenin kabulü', 'Kontrollü değişiklikten sonra hem bağlantı kurulmasını hem yetkisiz kaynakların hâlâ reddedilmesini sınayın. Normal ve yedek bağlantı durumlarını ayrı test edin. Aynı uygulamanın mevcut oturumu ile yeni oturumu farklı etkilenebilir. Geri dönüş planına eski rota tercihi, NAT ve güvenlik kurallarını birlikte koymak kısmi geri almanın yaratacağı tutarsızlığı önler.']
], [3704, 4787], 'varsayilan-ag-gecidi'),
article('ospf-alan-siniri-tasarimi', 'OSPF alan sınırını bina sınırına göre çizmek yeterli mi?', true,
'OSPF alan tasarımı fiziksel haritadan fazlasını gerektirir. Bağlantı yapısı, değişim sıklığı ve işletim sorumlulukları alan planına birlikte yansıtılmalıdır.', [
['Mantıksal topolojiyi çıkarın', 'OSPF bağlantı durumu bilgisi ve alan yapısıyla çalışır. Alanlar tasarımın ölçeğini ve bilgi dağılımını düzenlemeye yardımcı olur; ancak her binayı ayrı alan yapmak kendiliğinden iyi tasarım değildir. Binalar arasında çapraz bağlantılar, yedek yollar ve ortak servisler varsa çizimdeki basit sınır işletimde karmaşık hâle gelebilir. Önce yönlendiricileri ve gerçek transit ilişkilerini gösterin.'],
['Kampüs örneği', 'İki binanın tek bir dağıtım çifti üzerinden merkeze bağlandığını düşünün. Fiziksel olarak iki bina olsa da arıza alanları ve yönlendirme sorumluluğu ortak olabilir. Ayrı alan önerisinin hangi problemi çözdüğünü yazın: LSA kapsamı mı, özetleme mi, yönetim sınırı mı? Gerekçe yalnızca haritada temiz görünmesiyse tasarımı yeniden değerlendirin. Küçük bir ağda gereksiz alanlar daha fazla işletim yükü yaratabilir.'],
['Geçiş kontrolü', 'Alan kimliği, ağ türü, kimlik doğrulama, MTU ve zamanlayıcı uyumunu mevcut komşuluklarla birlikte inceleyin. Komşuluk kurulması bütün rotaların doğru ilan edildiğini kanıtlamaz. Laboratuvarda bir bağlantıyı ve bir dağıtım cihazını ayrı ayrı kaybedin; erişim yolunu ve uygulama etkisini gözlemleyin. Üretim cihazında rastgele zamanlayıcı düşürerek yakınsamayı hızlandırmaya çalışmayın.'],
['İşletilebilirlik ölçütü', 'Nöbetçi mühendisin arızayı hangi alan ve cihazlarla sınırlayabileceği belli olmalıdır. Alanlar arası özetler, varsayılan rotalar ve istisnalar tek belgede gösterilmelidir. Ağ büyüdüğünde yeni şubenin nasıl ekleneceğini bir örnekle sınayın. İyi OSPF planı yalnızca kısa rota tablosu üretmez; beklenen ve beklenmeyen davranışın ekip tarafından anlaşılmasını sağlar.']
], [2328, 4632], 'cidr-alt-ag-hesaplama'),
article('bgp-varsayilan-reddet-politikasi', 'eBGP oturumu açılmadan önce hangi politikalar hazırlanmalı?', true,
'BGP komşuluğunun kurulması rota alışverişinin güvenli veya doğru olduğu anlamına gelmez. İçe ve dışa aktarım kapsamını bağlantıdan önce açıkça belirleyin.', [
['Oturum ile rota politikası', 'RFC 8212, açık içe ve dışa aktarım politikası bulunmadığında eBGP rota alışverişi için varsayılan reddet yaklaşımını tanımlar. Yine de kullandığınız ürün ve sürümün gerçek varsayılanını doğrulamalısınız. Tasarımınızı cihazın bilinmeyen varsayılanına bağlamayın. Hangi öneklerin kabul edileceğini, hangilerinin ilan edileceğini ve beklenen sayı aralığını yazılı hâle getirin.'],
['Şube sağlayıcı bağlantısı', 'Bir şubenin yalnızca varsayılan rota alması ve kendisine ait tek bloğu duyurması gerektiğini düşünün. Tam internet tablosunu kabul etmek gereksiz kaynak tüketimine yol açabilir; başka yerlerden öğrenilmiş rotaları dışarı aktarmak da istenmeyen transit davranışı oluşturabilir. Filtreyi önce laboratuvarda izinli ve yasak örneklerle değerlendirin. Bir öneğin içe alınması onun dışa ilan edilmesini gerektirmez.'],
['Yayın öncesi kayıt', 'Komşu ASN, adres ailesi, önek listesi, maksimum rota sınırı ve alarm sahibini kaydedin. Maksimum rota sınırının aşılmasında cihazın yalnızca alarm mı verdiğini yoksa oturumu mu kapattığını öğrenin. Yanlış eşik hizmet kesintisine neden olabilir. İlk kurulumda politika sonucunu alınan, kabul edilen ve ilan edilen rota görünümleri üzerinden karşılaştırın.'],
['Değişiklik sonrası doğrulama', 'Oturumun established görünmesini son kontrol saymayın. Gerçek öneklerin doğru özelliklerle taşındığını ve yasak örneklerin çıkmadığını doğrulayın. Sağlayıcının gördüğü rota bilgisiyle yerel çıktıyı mümkün olduğunda karşılaştırın. Geri dönüş planında yalnızca komşuluğu kapatmak değil, önceki erişim yolunun nasıl korunacağı da bulunmalıdır.']
], [8212, 7454], 'varsayilan-ag-gecidi'),
article('bfd-zamanlayici-kapasite', 'BFD zamanlayıcılarını düşürmek her zaman daha iyi midir?', true,
'Hızlı arıza algılama hedefi cihaz kapasitesi ve ağ koşullarıyla uyumlu olmalıdır. BFD’nin algılama süresini uygulamanın toplam toparlanma süresiyle karıştırmayın.', [
['Algılama yalnızca bir aşama', 'BFD iki uç arasındaki iletim yolunun canlılığını izlemeye yönelik bir mekanizmadır. Bir arızayı hızlı fark etmek, yönlendirme kararının uygulanması ve uygulamanın yeniden bağlanmasının da aynı sürede biteceğini göstermez. Kontrol düzlemi yükü, zamanlayıcı desteği ve oturum sayısı mühendislik hesabına girer. Çok kısa aralıklar uygun olmayan cihazda yanlış kayıp algısına veya gereksiz komşuluk değişimine yol açabilir.'],
['Uzak şube örneği', 'Merkez ile şube arasındaki bağlantı zaman zaman kısa gecikme artışları yaşıyor olsun. Çok sıkı algılama hedefi, kullanıcıların tolere edebileceği geçici dalgalanmayı bağlantı arızası olarak yorumlayabilir. Önce normal koşullardaki gecikme ve kaybı ölçün, sonra ürünün desteklediği zamanlayıcıları değerlendirin. Varsayımsal milisaniye değerini bütün şubelere kopyalamak yerine sınıflandırılmış bağlantı profilleri oluşturun.'],
['Test planı', 'Fiziksel bağlantı kesilmesi, karşı cihaz kapanması ve tek yönlü iletim sorunu farklı senaryolardır. Laboratuvarda her birinde BFD durumu, rota değişimi ve uygulama toparlanmasını ayrı zaman damgalarıyla kaydedin. Saat doğruluğu ölçüm hassasiyetini sınırlar. Sadece arayüz kablosunu çıkarmak, tüm arızaların aynı şekilde algılanacağını kanıtlamaz.'],
['İşletim eşiği', 'Başarı ölçütü en küçük sayı değil, hizmet hedefini kararlı biçimde karşılayan ayardır. Değişiklikten sonra flap sayısını, işlemci yükünü ve oturum kararlılığını izleyin. Geri dönüş koşulunu önceden belirleyin; yanlış algılamalar yükseldiğinde hangi profile dönüleceği belli olsun. Bu kayıt, hız talebi ile güvenilir işletim arasındaki kararın görünür olmasını sağlar.']
], [5880, 2328], 'hiz-testi-dogru-olcum'),
article('dscp-guven-siniri', 'DSCP işaretlerine nerede güvenilmelidir?', true,
'Paketin yüksek öncelik istemesi, ağın bu isteği koşulsuz kabul etmesini gerektirmez. QoS tasarımında sınıflandırma ve güven sınırını açıkça belirleyin.', [
['İşaret bir politika girdisidir', 'DSCP, farklılaştırılmış hizmet davranışları için paket üzerindeki sınıflandırma bilgisidir. İşaretin bulunması uçtan uca gecikme veya bant genişliği garantisi vermez. Her ağ bölümü kendi politikasını uygular; sağlayıcı sınırında işaret korunabilir, yeniden yazılabilir veya dikkate alınmayabilir. Bu nedenle yalnızca paket yakalamasında yüksek öncelik değeri görmek hizmet hedefinin karşılandığını kanıtlamaz.'],
['Telefon ve misafir istemci', 'Kurumsal telefonların işaretlerine yönetilen bir erişim portunda güvenilebilirken misafir istemcilerin bütün trafiği yüksek öncelikle etiketlemesi kabul edilmemelidir. Sınıflandırmayı cihaz kimliği, port rolü veya uygulama bilgisiyle destekleyin. Kullanıcı ağından gelen bütün işaretleri aynen taşımak öncelikli kuyruğu sıradan indirmelerle doldurabilir. Politikanın hangi sınırda uygulandığı çizimde görünmelidir.'],
['Doğrulama yöntemi', 'İzinli testte gerçek zamanlı akış ve arka plan aktarımı birlikte çalıştırın. Girişteki işaret, çıkıştaki işaret, kuyruk sayaçları ve uygulama gecikmesini aynı pencerede inceleyin. Trafik yokken başarılı telefon görüşmesi, tıkanıklık altındaki politikanın çalıştığını kanıtlamaz. Yük testinin canlı kullanıcıları etkilemeyeceği kontrollü bir ortam seçin.'],
['Sınıfları sade tutmak', 'Her uygulamaya ayrı sınıf açmak yönetimi zorlaştırabilir. İş gereksinimlerine göre az sayıda anlaşılır sınıf belirleyin; her sınıfın neden var olduğunu ve nasıl ölçüleceğini yazın. Öncelikli kuyruğun sınırları ve kalan trafiğin hizmeti birlikte planlanmalıdır. Şirket dışındaki bir ağın aynı sınıfları kullanacağını varsaymayın; hizmet sözleşmesinde tanımlanan davranışı ve sınırları sağlayıcıyla doğrulayın. QoS eksik kapasiteyi sınırsız kaynağa dönüştürmez; tıkanıklık olduğunda kaynakların nasıl paylaşılacağını düzenler.']
], [2474, 4594], 'hiz-testi-dogru-olcum'),
article('kuyruk-buyuklugu-gecikme', 'Büyük tampon neden hızlı hattı yavaş hissettirebilir?', true,
'Bir bağlantının yüksek aktarım kapasitesi, yoğun yük altında düşük gecikme sunacağını garanti etmez. Kuyruk davranışını boş ve yüklü koşullarda birlikte ölçün.', [
['Bekleme süresini görünür kılmak', 'Paketlerin çıkış kapasitesini beklediği kuyruk büyüdüğünde gecikme artabilir. Daha fazla tampon her zaman daha iyi kullanıcı deneyimi değildir. Aktif kuyruk yönetimi, tıkanıklığı yönetmek için çeşitli işaretleme veya düşürme yaklaşımları kullanabilir. Hangi algoritmanın uygun olduğu cihaz ve trafik profilinde sınanmalıdır; tek bir evrensel tampon boyutu bütün ağlara uygulanamaz.'],
['Evden çalışma örneği', 'Büyük yedekleme yüklenirken görüntülü görüşmenin gecikmesi artsın. Önce boşta gecikmeyi, ardından aynı hedefe kontrollü yük altındaki gecikmeyi karşılaştırın. Upload yönünün dolması, download kapasitesi boş görünse de etkileşimi bozabilir. Kablosuz yeniden iletimleri ve uzak sunucu yükünü ayrı olasılıklar olarak tutun; her yüksek gecikmeyi otomatik olarak bufferbloat diye adlandırmayın.'],
['Ölçüm düzeni', 'Testte bağlantı türünü, yük yönünü, eşzamanlı uygulamaları ve ölçüm süresini kaydedin. Ortalama yanında dağılımı veya yüksek yüzdelikleri inceleyin; kısa kötü dönemler ortalamada kaybolabilir. Deneysel ayar değişikliğini tek seferde bir parametreyle sınayın. Değişiklik sonrası aktarım kapasitesi çok düşüyorsa gecikme kazanımının bedelini de rapora ekleyin.'],
['Kalıcı işletim', 'Darboğazın hangi arayüzde olduğunu bulmadan rastgele kuyruk ayarı yapmak sonuç vermeyebilir. Şekillendirme uygulanıyorsa gerçek çıkış kapasitesiyle uyumunu ve sağlayıcı koşullarını değerlendirin. Başarıyı yalnızca hız testi sayısıyla değil, yoğun kullanım sırasında görüşme veya uzaktan masaüstü gibi gerçek etkileşimle doğrulayın. Kullanıcı deneyimi, kapasite ve gecikmenin birlikte değerlendirilmesini gerektirir.']
], [7567, 6349], 'hiz-testi-dogru-olcum'),
article('uygulama-gecikme-butcesi', 'Bir uygulama için ağ gecikme bütçesi nasıl hazırlanır?', true,
'Sayfanın geç açılması tek bir ağ gecikmesi sayısına indirgenemez. İsim çözümü, bağlantı kurulumu, sunucu işlemi ve veri aktarımını ayrı aşamalarda değerlendirin.', [
['Ölçülen aralığı tanımlamak', 'Tek yönlü ağ gecikmesi ile gidiş dönüş süresi farklı ölçülerdir. Tek yönlü ölçümde saat eşzamanlaması ve ölçüm belirsizliği ayrıca önemlidir. Uygulama süresi bunlara sunucu işlemi ve istemci çalışmasını ekler. Önce “hızlı” hedefinin hangi kullanıcı eylemi için geçerli olduğunu yazın: ilk ekran, arama sonucu veya dosya indirme aynı bütçeye sahip olmayabilir.'],
['Örnek kullanıcı akışı', 'Bir operatör envanter ekranında filtre değiştiriyor olsun. İşlem; tarayıcı kodu, API isteği, veritabanı sorgusu ve ekran çiziminden oluşabilir. Ağ RTT’sini azaltmak yavaş veritabanı sorgusunu ortadan kaldırmaz. Tarayıcı ve sunucu zaman çizelgelerini ilişkilendirin; ancak farklı saatlerden gelen değerleri doğrudan çıkarırken doğruluk sınırını belirtin. Bu örnekte sayı vermek yerine her aşamanın ölçüm kaynağını tanımlamak ilk doğru adımdır.'],
['Bütçe dağıtımı', 'Toplam hedefin hangi bölümünün ağ, sunucu ve istemci için ayrıldığını ekiplerle kararlaştırın. Ortalamaya ek olarak yoğun saat ve yüksek yüzdelik sonuçlarını takip edin. Tek bir kullanıcının hızlı bağlantısında yapılan test uzak şubeleri temsil etmez. Gözlem noktalarını ve örnek sayısını rapora yazın; eksik kapsama sahip testleri genel garanti gibi sunmayın.'],
['Değişiklik kararını vermek', 'Önce toplam sürede en büyük ve değiştirilebilir paya sahip aşamayı iyileştirin. Her değişiklikten sonra aynı akışı aynı koşullarda yeniden ölçün. Ağ iyileştirmesiyle uygulama sürümü aynı anda değişirse hangi müdahalenin etki yarattığını ayırmak zorlaşır. Bütçe, ekipler arasında suç paylaşma aracı değil, kullanıcı hedefini parçalara ayıran ortak ölçüm sözleşmesidir.']
], [7679, 6349], 'hiz-testi-dogru-olcum'),
article('ag-ariza-alani-haritasi', 'İki bağlantı gerçekten iki bağımsız arıza alanı mı?', true,
'Yedeklilik sayısı kablo sayısından ibaret değildir. Ortak enerji, güzergâh, kontrol düzlemi ve işletim bağımlılıklarını görünür kılın.', [
['Bağımsızlık varsayımını açmak', 'İki uplink aynı şasiye, aynı elektrik hattına veya aynı fiziksel kanala bağlıysa bazı arızalarda birlikte kaybolabilir. Yönlendirme protokolünün alternatif yol göstermesi fiziksel bağımsızlığı kanıtlamaz. Ağ diyagramına mantıksal bağlantıların yanında ortak bağımlılıkları ekleyin. BFD veya benzeri canlılık mekanizması arızayı fark edebilir; ortak bağımlılığı ortadan kaldırmaz.'],
['Şube bağlantısı örneği', 'İki servis sağlayıcıdan hizmet alan şubenin son erişim kabloları aynı bina girişinden geçiyor olsun. Sağlayıcı isimleri farklı olsa da kazı veya bina arızası her ikisini etkileyebilir. Mümkün olan bağımsızlık düzeyini sözleşme ve saha bilgisiyle doğrulayın. Bakım ekiplerinin aynı anda iki yolu devre dışı bırakmaması için değişiklik takvimlerini de ortak bağımlılık olarak değerlendirin. Belgesi olmayan güzergâhı bağımsız diye raporlamak yerine bilinmiyor olarak işaretlemek daha yararlıdır.'],
['Hata matrisi hazırlamak', 'Kablo, port, cihaz, enerji, sağlayıcı ve yönetim hatası satırlarından oluşan bir matris kurun. Her satır için hangi hizmetlerin etkilendiğini, algılama yöntemini ve geri dönüş yolunu yazın. Bazı senaryolar üretimde güvenle test edilemeyebilir; masa başı incelemeyi gerçek arıza testiyle aynı kanıt düzeyi olarak sunmayın. Her bulgunun kaynağı görünür olmalıdır.'],
['Önceliklendirme', 'Bütün ortak riskleri ortadan kaldırmak mümkün olmayabilir. İş etkisi yüksek ve giderilmesi uygulanabilir olanları önce ele alın. Yedek yolun kapasitesinin kritik hizmetlere yetip yetmediğini sınayın; yalnızca rotanın değişmesi işin devam ettiği anlamına gelmez. İyi arıza haritası, hangi koşulda hizmetin süreceğini ve hangi koşulda kurtarma planına geçileceğini açıkça anlatır.']
], [5880, 4786], 'varsayilan-ag-gecidi'),
article('overlay-mtu-hesabi', 'VXLAN ve tünellerde MTU hesabı nereden başlar?', true,
'Kapsülleme, iç pakete dış başlıklar ekler. Overlay tasarımında uçtaki MTU ile taşıyıcı ağın taşıyabileceği çerçeveyi birlikte hesaplayın.', [
['İç ve dış boyutu ayırmak', 'VXLAN, Ethernet çerçevelerini UDP tabanlı bir kapsülleme içinde taşır. Dış adres ailesi ve ek etiketler toplam boyutu etkiler. Bu nedenle “tünel ekledik ama MTU aynı kaldı” varsayımı güvenli değildir. Her başlığı nerede saydığınızı belirtin; cihazların L2 çerçeve boyutu ile L3 MTU için kullandığı terimler farklı olabilir. Ürün arayüzündeki sayının tam anlamını belgeden doğrulayın.'],
['Kontrol tablosu', 'Tabloya iç IP paketi, iç Ethernet başlığı, varsa VLAN etiketi, tünel başlığı, UDP ve dış IP başlığını ayrı satırlarda yazın. Gerektiğinde dış Ethernet alanlarını da fiziksel sınır hesabına ekleyin. Tek bir ezberlenmiş ek yük değerini bütün IPv4 ve IPv6 tünellerine kopyalamayın. Amaç hesap makinesindeki güzel sayı değil, uçtan uca desteklenen boyutu bulmaktır.'],
['Laboratuvar deneyi', 'İki uç arasında farklı paket boyutlarıyla kontrollü test yapın ve gerçek uygulama aktarımını ekleyin. Yol üzerindeki bütün cihazların ayarı aynı olmak zorunda olmayabilir; en dar sınır önemlidir. Küçük kontrol paketleri başarılıyken büyük veri paketleri düşebilir. Bu yüzden yalnızca komşuluk ve ping durumunu sağlıklı görmek overlay’in tüm boyutlarda çalıştığını kanıtlamaz.'],
['Değişiklik güvenliği', 'Jumbo frame etkinleştirmeyi tek bir switch üzerinde yapıp tamamlandı saymayın. Taşıyıcı yolun tamamını, ara güvenlik cihazlarını ve yedek yolu kapsayın. Değişiklikten sonra parçalanma, düşürme ve uygulama hatalarını gözlemleyin. Yedek yola geçildiğinde daha küçük MTU oluşabiliyorsa bu durum da kabul testinin parçasıdır.']
], [7348, 8900], 'ping-yaniti-yok'),
article('kapasite-yuzdelik-planlama', 'Kapasite planında ortalama trafik neden yetersizdir?', true,
'Günlük ortalama kullanım düşük olsa da kısa yoğunluklar kullanıcıları etkileyebilir. Zaman penceresini ve yüzdelik hesabını açık tutarak kapasite kararını veriye dayandırın.', [
['Örnekleme kararın parçasıdır', 'Beş dakikalık ortalama kısa süreli patlamaları yumuşatır. Bir saniyelik örnekler daha fazla ayrıntı sunar ancak toplama maliyeti ve sayaç doğruluğu gerekir. Kullanılan örnek aralığı raporda yoksa yüzde 95 değeri de bağlamını kaybeder. Yüzdelik, tek başına hizmet kalitesi veya sözleşmedeki faturalama ölçütü değildir; hesap yöntemi açıkça belirtilmelidir.'],
['Ofis yedekleme senaryosu', 'Gece yedeklemesi bağlantıyı dolduruyor, gündüz kısa toplantı yoğunlukları sorun yaratıyor olsun. Bütün günün ortalaması iki davranışı gizleyebilir. İş saatleri ve bakım saatlerini ayrı inceleyin; upload ve download yönlerini birleştirmeyin. Trafik miktarının yanında gecikme, düşürme ve uygulama şikâyeti zamanlarını eşleştirin. Yoğunluk her zaman kullanıcı sorunu demek değildir, fakat aynı pencerede görülen bozulma güçlü bir araştırma ipucudur.'],
['Hesabı doğrulamak', 'Arayüz sayaç farkını geçen süreye bölerek hız türetiyorsanız sayaç sıfırlanmasını ve taşmasını kontrol edin. Eksik örnekleri sıfır kullanım gibi doldurmak yüzdelikleri yapay biçimde düşürebilir. Örnek sayısını, veri boşluklarını ve bağlantı hızını saklayın. Sağlayıcı raporuyla kendi raporunuz farklıysa önce ölçüm noktası ve pencereyi eşitleyin.'],
['Yatırım kararı', 'Kapasite artışı, trafik zamanlaması veya kuyruk politikası seçeneklerini gerçek darboğaza göre karşılaştırın. Büyüme tahminini geçmişten çıkarırken yeni uygulama ve kullanıcı sayısını ayrıca değerlendirin. Gerekçesiz sabit yüzde eşikleri yerine iş hedefini koruyan baş boşluğu planlayın. Sonuç raporunda ölçülen veri ile gelecek varsayımını ayrı göstermek kararın denetlenmesini kolaylaştırır.']
], [2863, 7567], 'hiz-testi-dogru-olcum'),
article('arayuz-sayaci-sifirlanma', 'Arayüz sayacı sıfırlandığında yanlış trafik alarmı nasıl önlenir?', true,
'Kümülatif sayaçtan hız hesaplamak basit görünür, fakat yeniden başlatma ve sayaç süreksizliği sonuçları bozabilir. Ölçüm sisteminde bu durumları açıkça modelleyin.', [
['Fark alma varsayımı', 'İki sayaç değeri arasındaki fark, aynı sayacın kesintisiz arttığı varsayımıyla anlamlıdır. Cihaz yeniden başladığında veya arayüz yeniden oluşturulduğunda bu varsayım bozulabilir. IF-MIB yüksek kapasiteli sayaçlar ve süreksizlik bilgisi için tanımlar içerir. Yalnızca son değer önceki değerden küçük diye büyük bir trafik sıçraması üretmek yanlış alarm doğurur.'],
['Somut hesap örneği', 'İlk okumada 900 milyon, ikinci okumada 2 milyon bayt görülmüş olsun. Arada cihaz yeniden başladıysa negatif farkı işaretsiz sayıya çevirmek devasa trafik sonucu oluşturabilir. Önce çalışma süresi ve süreksizlik bilgisini kontrol edin. Bu aralık için oranı bilinmiyor olarak işaretlemek, sahte bir kesin sayı göstermekten daha doğrudur. Takip eden geçerli aralık normal hesaplanabilir.'],
['Arayüz kimliği', 'Arayüz indeksinin yeniden başlatma veya yapılandırma sonrası aynı fiziksel porta karşılık gelip gelmediğini doğrulayın. İzleme sistemi yalnızca indeksle eşliyorsa yanlış portun geçmişini devam ettirebilir. Kalıcı tanımlayıcı, açıklama ve cihaz bilgilerini birlikte kullanın; açıklama alanının da insanlar tarafından değiştirilebildiğini unutmayın. Haritalama değişikliği grafikte olay olarak görünmelidir.'],
['Test ve raporlama', 'Laboratuvarda yeniden başlatma, sayaç taşması ve veri boşluğu senaryolarını ayrı sınayın. Grafik sıfırla doldurmak yerine boşluğu gösterebilmeli; alarm motoru da aynı kalite bilgisini kullanmalıdır. Ham okumaları kısa süreyle saklamak hesap hatalarını incelemeyi kolaylaştırır. Kullanıcıya pürüzsüz ama yanlış grafik yerine ölçümün nerede güvenilir olduğunu gösteren bir görünüm sunun.']
], [2863, 8342], 'hiz-testi-dogru-olcum'),
article('ag-yapilandirmasi-geri-donus', 'Uzaktan ağ değişikliğinde geri dönüş planı nasıl somutlaştırılır?', true,
'“Sorun olursa eski ayara döneriz” yeterli bir plan değildir. Bağlantı kaybolduğunda eski ayarın kim tarafından, hangi erişim yoluyla geri yükleneceğini belirleyin.', [
['Üç ayrı durumu kaydedin', 'İstenen yapılandırma, cihazın kabul ettiği yapılandırma ve gerçekten çalışan durum farklı olabilir. NETCONF gibi yönetim mekanizmaları yapılandırma işlemleri için belirli yetenekler sunar; ancak her cihaz aynı yetenekleri desteklemez. Geri dönüşü ürününüzde doğrulanmış özelliklere dayandırın. Confirmed commit benzeri mekanizmanın varlığını, süresini ve bağlantı kopunca davranışını belge üzerinden ve testle kontrol edin.'],
['Yönetim VLAN’ı örneği', 'Uzaktan bağlı olduğunuz cihazın yönetim VLAN’ını değiştireceksiniz. Önce yeni yolun upstream izinlerini ve dönüş rotasını hazırlayın. Eski erişimi kaldırmadan yeni erişimi bağımsız oturumla doğrulayın. Yönetim oturumunun devam etmesi yeni bağlantıların kurulabildiğini kanıtlamaz; açık oturum önbellek veya mevcut durum sayesinde sürebilir. Ayrı bir bağlantı denemesi bu yüzden önemlidir.'],
['Geri dönüş kaydı', 'Eski yapılandırmayı, değişecek satırları, başarı kontrolünü, zaman sınırını ve sorumlu kişiyi yazın. Konsol veya bağımsız yönetim erişimi yoksa bu sınırlılığı açıkça belirtin. Bir komut listesi hazırlamak yeterli değildir; komutları çalıştıracak yol kesildiğinde plan işlemelidir. Aynı anda başka ekiplerin ilgili cihazlarda değişiklik yapmadığını da koordinasyon kaydına ekleyin.'],
['Kapatma ölçütü', 'Değişiklik sonrası yönetim erişimi, yönlendirme, güvenlik kuralı ve gerçek kullanıcı akışını kontrol edin. Çalışan durumu kalıcı kayda alma adımı platforma göre farklı olabilir. Ertesi yeniden başlatmada eski yapılandırmaya dönme riskini doğrulayın. Başarıyı yalnızca komutların hata vermemesi üzerinden raporlamayın; hedeflenen davranışın gerçekleşmesi gerekir.']
], [6241, 8342], 'varsayilan-ag-gecidi'),
article('rota-yeniden-dagitim-dongusu', 'Rota yeniden dağıtımında geri besleme nasıl önlenir?', true,
'İki yönlendirme alanı arasında rota paylaşımı çift yönlü açıldığında köken bilgisi kaybolabilir. İçe alınan rotanın yeniden kendi kaynağına dönmesini politika ile önleyin.', [
['Sınırın amacını yazmak', 'Redistribution, bir yönlendirme kaynağındaki rotaları başka bir mekanizmaya taşır. Protokoller metrik ve özellikleri aynı anlamda kullanmayabilir. “Her şeyi iki tarafa aktar” yaklaşımı, beklenmedik tercih ve geri besleme davranışı yaratabilir. Önce hangi ağların neden paylaşılacağını, hangi varsayılanların taşınacağını ve hangi rotaların kesinlikle dışarı çıkmayacağını belirleyin.'],
['İki geçişli örnek', 'A ve B yönlendirme alanları iki sınır yönlendiricisi üzerinden bağlı olsun. A’dan B’ye alınan bir rota diğer sınırda tekrar A’ya aktarılırsa kaynağı farklıymış gibi değerlendirilebilir. Etiketleme ve filtreleme bazı tasarımlarda kökeni korumaya yardımcı olur; ancak etiketin protokoller arasında taşınıp taşınmadığı platforma bağlıdır. Sadece etiketi ayarlamak yerine ilan edilen rotada gerçekten kaldığını doğrulayın.'],
['Kontrollü kapsam', 'Önce az sayıda açık önekle başlayın. Birincil ve yedek sınır durumlarında seçilen rotayı inceleyin. Bir rotanın çekilmesi, tekrar gelmesi ve sınır cihazının yeniden başlaması ayrı testlerdir. Normal durumda doğru yolun seçilmesi arıza anında döngü oluşmayacağını kanıtlamaz. Varsayılan rota yeniden dağıtımı özellikle açık bir gerekçe ve sınır gerektirir.'],
['Daha sade seçenekler', 'İki alanın gerçekten çift yönlü tam rota bilgisine ihtiyacı olup olmadığını sorgulayın. Özet veya kontrollü varsayılan rota bazı tasarımlarda daha anlaşılır olabilir. Ancak bu sadeleştirme boşluk ve arıza davranışını değiştirebilir. Kararı rota sayısına bakarak değil, erişim gereksinimi ve hata senaryolarıyla verin. Politikanın sahibi ve değişiklik yöntemi merkezi kayıtta bulunmalıdır.']
], [2328, 4271], 'varsayilan-ag-gecidi'),
article('vrf-cakisan-adresler', 'Aynı IP adresi iki VRF içinde nasıl kullanılabilir?', true,
'VRF, yönlendirme bağlamlarını ayırabilir. Aynı adresin farklı bağlamlarda bulunması mümkündür; ancak gözlem, güvenlik ve ortak hizmet tasarımı bu ayrımı korumalıdır.', [
['Adresin bağlamı büyür', 'Birden fazla yönlendirme tablosu bulunan tasarımda hedef yalnızca IP’den ibaret değildir; hangi VRF içinde değerlendirildiği de önemlidir. RFC 4364, BGP/MPLS VPN bağlamında bu ayrımın kullanımını açıklar. Her VRF uygulaması otomatik olarak MPLS kullanmaz. Kavramı ürün adıyla eşitlemeden önce yerel mimarinin hangi izolasyon mekanizmasını kullandığını belirleyin.'],
['İki kiracı örneği', 'Kiracı A ve B kendi 192.168.10.10 sunucularını kullanıyor olsun. Envanter anahtarı yalnızca IP ise iki sunucu yanlış birleştirilir. Alarmın hangi kiracının sorumlusuna gideceği de aynı bağlam bilgisinden türetilmelidir; aksi durumda olay yanlış ekibe yönlenebilir. Kayda kiracı, VRF, cihaz ve gözlem kaynağını ekleyin. Tanılama komutunun doğru VRF içinde çalıştığını doğrulayın; varsayılan tabloda başarısız olan ping, ilgili kiracı ağının kapalı olduğunu kanıtlamaz.'],
['Ortak hizmet sorusu', 'İki kiracı ortak DNS veya güncelleme sunucusuna erişecekse kontrollü rota paylaşımı, güvenlik politikası ve olası adres çakışması birlikte ele alınır. VRF ayrımı kendi başına bütün güvenlik ihtiyaçlarını karşılamaz. Ortak hizmetin yanıtları doğru bağlama döndürebilmesi gerekir. Çakışan kaynak adreslerin günlüklerde nasıl ayırt edileceğini çözmeden yalnızca bağlantıyı açmak işletimi zorlaştırır.'],
['Doğrulama', 'Her kiracıdan izinli hizmete erişimi ve diğer kiracıya yasak erişimi ayrı test edin. İzleme ve yedekleme sistemlerinin de doğru bağlamı seçtiğini kontrol edin. Rota paylaşımı değişikliklerinde etkilenen önekleri açık listeyle sınırlandırın. Başarılı tasarım, aynı numaraların kullanılabilmesinden çok, bu numaraların yanlış güvenlik veya envanter bağlamına taşınmamasıyla değerlendirilir.']
], [4364, 3704], 'ozel-ip-araliklari'),
article('igmp-uyelik-ve-multicast-yolu', 'IGMP üyeliği multicast yayının ulaştığını kanıtlar mı?', true,
'Bir alıcının gruba katılması multicast veri yolunun yalnızca bir parçasıdır. Kaynak, grup, switch davranışı ve yönlendirmeyi ayrı gözlemleyin.', [
['Kontrol mesajı ile veri akışı', 'IGMP, IPv4 multicast grup üyeliğinin bildirilmesi için kullanılır; IGMPv3 kaynak filtreleme yetenekleri de tanımlar. Üyelik kaydının varlığı göndericinin veri ürettiğini veya yolun tamamının doğru olduğunu garanti etmez. Ayrıca switch üzerindeki snooping davranışı yönlendirici üyelik işlemiyle aynı şey değildir. Her cihazın hangi rolü üstlendiğini diyagramda belirtin.'],
['Kamera yayını örneği', 'İzleme uygulaması gruba katılıyor ama görüntü yok olsun. Önce kameranın doğru kaynak ve gruba veri gönderdiğini doğrulayın. Sonra alıcının üyelik bilgisini ve veri paketlerinin ilgili switch çıkışında görülüp görülmediğini inceleyin. Başka VLAN’daki alıcı için multicast yönlendirme gerekebilir. Unicast kameraya erişimin çalışması multicast veri yolunu kanıtlamaz.'],
['Kaynak filtresi', 'Aynı grup adresine birden fazla kaynak gönderiyorsa alıcının hangi kaynağı istediği önem kazanır. Kaynak adres değişikliği, grup aynı kaldığı hâlde uygulamanın veri alamamasına yol açabilir. Destek kaydına yalnızca grup adresini değil kaynak adresi, üyelik modu ve alıcı arayüzünü ekleyin. Bu bilgiler olmadan iki testin gerçekten aynı akışı kullandığını söylemek zordur.'],
['Zaman içindeki davranış', 'Uygulama başlarken çalışan yayının daha sonra kesilmesi üyelik yenileme veya ağ durumu değişikliğiyle ilişkili olabilir. Başlangıç ekran görüntüsü yerine üyelik ve veri akışını bir süre izleyin. Gereksiz multicast yayılımını önlemek kadar meşru alıcıların sürekliliği de önemlidir. Düzeltme sonrası birden fazla alıcı, farklı VLAN ve uygulama yeniden başlatma durumlarını kontrollü olarak sınayın.']
], [3376, 919], 'ipv6-komsu-kesfi'),
article('ag-gunlukleri-saat-korelasyonu', 'Ağ günlüklerini birleştirirken saat farkı nasıl hesaba katılır?', true,
'İki cihazın olay sırası, saatleri uyumsuzsa ters görünebilir. Zaman damgasını yalnızca tarih metni olarak değil, belirsizliği olan ölçüm bilgisi olarak ele alın.', [
['Saat dilimi başka, saat doğruluğu başka', 'UTC kullanmak gösterim tutarlılığı sağlar; cihaz saatinin doğru olduğunu garanti etmez. NTP gibi eşzamanlama mekanizmalarının durumu ayrıca izlenmelidir. Tek yönlü gecikme hesabında saat farkı özellikle önemlidir. Günlükteki milisaniye basamakları gerçek doğruluğun milisaniye düzeyinde olduğunu kanıtlamaz; yalnızca gösterim çözünürlüğü olabilir.'],
['Olay incelemesi örneği', 'Güvenlik duvarı bağlantı reddini 10:00:03, sunucu bağlantı isteğini 10:00:01 olarak kaydetmiş olsun. Cihazlardan birinin saati birkaç saniye gerideyse bu sıralamadan kesin nedensellik çıkarılamaz. Her cihazın saat kaynağını ve bilinen sapmasını toplayın. Olayı tek zaman noktasına zorlamak yerine olası zaman aralığıyla eşleştirmek daha doğru olabilir.'],
['Toplama hattı', 'Olayın cihazda üretildiği zaman ile günlük sunucusuna ulaştığı zamanı ayrı alanlarda saklayın. Ağ gecikmesi veya tamponlama teslim zamanını değiştirebilir. Saat dilimi bilgisi içermeyen kayıtların yorumunu açıkça tanımlayın. Yaz saati değişimi veya yerel saat kullanımı aynı görünen iki zaman üretebilir; normalleştirme sırasında ham kaydı da koruyun.'],
['Doğrulama ve sınırlar', 'Kontrollü bir olay üretip ilgili cihazlarda nasıl göründüğünü karşılaştırın. Gerçek hassasiyetiniz saniye düzeyindeyse milisaniyelik arıza algılama sonucu raporlamayın. Saat kaynağı kaybı ve yeniden eşzamanlama durumlarını alarm tasarımına ekleyin. Olay incelemesinde yapılan zaman düzeltmesini kaydedin; ham zamanı sessizce değiştirmek sonradan yapılacak denetimin izini kaybettirir. İyi zaman yönetimi yalnızca düzgün grafik oluşturmaz; yanlış olay sırasına dayanarak hatalı kök neden seçilmesini önler.']
], [5905, 7679], 'windows-ag-teshis'),
article('bgp-onek-filtre-denetimi', 'BGP önek filtresi değişikliği nasıl test edilir?', true,
'Bir filtrede tek karakter değişmesi beklenenden geniş rota kümesini kabul edebilir. Pozitif ve negatif örnekleri değişiklik planının zorunlu parçası yapın.', [
['Eşleşmenin sınırını yazmak', 'Önek listesi yalnızca ağ adresinden oluşmaz; kabul edilen önek uzunluğu aralığı da önemlidir. Bir /16 bloğu ve altındaki belirli /24’leri kabul etmek, bütün daha özel rotaları kabul etmekle aynı değildir. Ürünün sözdizimini kendi belgesinden doğrulayın. Politika adının “güvenli” olması kuralın gerçekten dar olduğunu kanıtlamaz.'],
['Test tablosu hazırlamak', 'İzinli ana önek, izinli alt önek, fazla özel önek, komşu blok ve varsayılan rota için beklenen sonuçları yazın. Örneğin belirli bir şube bloğu için hazırlanmış filtre varsayılan rotayı yanlışlıkla kabul etmemelidir. Bu örnekleri otomatik test veya laboratuvar politika değerlendirmesiyle sınayın. Yalnızca beklenen rotanın geçtiğini görmek, beklenmeyenlerin engellendiğini göstermez.'],
['İki yönü ayırmak', 'İçe aktarım filtresi ile dışa aktarım filtresinin amaçları farklıdır. Bir sağlayıcıdan kabul edilen rota, başka sağlayıcıya ilan edilmemelidir diye bir iş kuralı bulunabilir. Değişikliğin hangi komşuya, adres ailesine ve yöne uygulandığını kaydedin. Aynı politika adı birden fazla yerde kullanılıyorsa etki alanı tek bağlantıdan geniş olabilir. Önce başvuru noktalarını envanterleyin.'],
['Canlı doğrulama', 'Değişiklikten sonra alınan, kabul edilen ve ilan edilen rotaları ayrı karşılaştırın. Beklenen rota sayısı yardımcı bir sinyaldir fakat aynı sayıda yanlış rota bulunabileceği için önek içeriğini de kontrol edin. Oturum yenileme veya route refresh davranışını ürününüzde doğrulayın. Geri dönüşte eski politika sürümünün yanında doğrulanmış rota görünümünü de saklamak, gerçekten eski duruma dönüldüğünü kanıtlar.']
], [7454, 8212], 'cidr-alt-ag-hesaplama'),
];
